CREATE OR REPLACE FUNCTION public.approve_finance_tax_correction(p_id uuid, p_reviewed_snapshot_json jsonb, p_legal_acknowledged boolean, p_review_evidence text, p_original_recovered boolean)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare c public.finance_tax_document_corrections%rowtype;
begin
 select * into strict c from public.finance_tax_document_corrections where id=p_id for update;
 if public.tax_correction_authorized(c.original_combined_document_id is not null,'issue') is distinct from true then raise exception 'TAX_CORRECTION_PERMISSION_DENIED'; end if;
 if c.draft_snapshot_json is distinct from p_reviewed_snapshot_json then raise exception 'TAX_CORRECTION_STALE_REVIEW'; end if;
 if p_legal_acknowledged is distinct from true or length(btrim(coalesce(p_review_evidence,'')))<5
   or (c.correction_mode='cancel_and_reissue' and p_original_recovered is distinct from true)
 then raise exception 'TAX_CORRECTION_LEGAL_REVIEW_REQUIRED'; end if;
 if c.status='approved' then return c.id; end if;
 if c.status<>'draft' then raise exception 'TAX_CORRECTION_DRAFT_REQUIRED'; end if;
 update public.finance_tax_document_corrections set status='approved',approved_at=now(),approved_by_user_id=auth.uid(),approval_evidence=btrim(p_review_evidence) where id=c.id;
 insert into public.finance_tax_correction_audit_events(correction_id,event_type,event_payload_json,actor_user_id)
 values(c.id,'approved',jsonb_build_object('legal_acknowledged',true,'review_evidence',p_review_evidence,'original_recovered_and_cancelled',p_original_recovered,'reviewed_snapshot',p_reviewed_snapshot_json),auth.uid());
 return c.id;
end;
$function$

CREATE OR REPLACE FUNCTION public.approve_retired_template_use_for_fee_agreement(p_fee_agreement_id uuid, p_reason text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_agreement public.finance_fee_agreements%rowtype; v_retired boolean;
begin
  if not public.current_user_is_document_platform_partner() then raise exception 'Only a Partner can approve continued use of a retired template'; end if;
  select * into v_agreement from public.finance_fee_agreements where id = p_fee_agreement_id for update;
  if v_agreement.id is null or v_agreement.status not in ('draft', 'under_review') or v_agreement.selected_template_version_id is null then raise exception 'Fee agreement is not eligible for retired template approval'; end if;
  select tv.status = 'retired' or t.status = 'retired' into v_retired from public.document_template_versions tv join public.document_templates t on t.id = tv.template_id where tv.id = v_agreement.selected_template_version_id;
  if not coalesce(v_retired, false) or btrim(coalesce(p_reason, '')) = '' then raise exception 'A reason is required to approve continued use of a retired template'; end if;
  update public.finance_fee_agreements set retired_template_use_approved_version_id = v_agreement.selected_template_version_id, retired_template_use_approved_by_user_id = auth.uid(), retired_template_use_approved_at = now(), retired_template_use_reason = btrim(p_reason), updated_by_user_id = auth.uid(), updated_at = now() where id = v_agreement.id;
  perform public.document_platform_audit('template_version', v_agreement.selected_template_version_id, 'approved_retired_use', jsonb_build_object('fee_agreement_id', v_agreement.id, 'reason', btrim(p_reason)));
  return v_agreement.id;
end;
$function$

CREATE OR REPLACE FUNCTION public.bridge_finance_legacy_expense(p_legacy_id text, p_id uuid, p_reason text, p_acknowledged boolean)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare l jsonb;existing uuid;
begin
 if not public.expense_can_manage() then raise exception 'EXPENSE_PERMISSION_DENIED'; end if;
 if p_acknowledged is distinct from true or nullif(btrim(p_reason),'') is null or p_id is null then raise exception 'EXPENSE_ACK_REASON_REQUIRED'; end if;
 perform pg_advisory_xact_lock(hashtextextended('legacy_expense:'||p_legacy_id,0));
 select to_jsonb(c) into l from public.finance_expense_claims c where c.id::text=p_legacy_id for update;
 select id into existing from public.finance_expenses where legacy_claim_id=p_legacy_id;
 if existing is not null then return existing; end if;
 if l is null or l->>'status' not in ('submitted','approved') or l->>'ledger_entry_id' is not null
  or exists(select 1 from public.finance_company_ledger x where to_jsonb(x)->>'source_expense_claim_id'=p_legacy_id)
  or not exists(select 1 from public.user_profiles where id=nullif(l->>'claimant_user_id','')::uuid and active)
 then raise exception 'EXPENSE_LEGACY_BRIDGE_INELIGIBLE'; end if;
 insert into public.finance_expenses(id,origin,legacy_claim_id,status,expense_date,description,category,claimant_id,client_id,case_id,advisory_matter_id,
  gross_amount,personally_paid,reimbursement_requested,note,submitted_at,created_by,updated_by)
 values(p_id,'legacy_claim',p_legacy_id,'submitted',(l->>'claim_date')::date,coalesce(nullif(btrim(l->>'description'),''),'Legacy expense claim'),
  coalesce(nullif(btrim(l->>'category'),''),'Legacy'),(l->>'claimant_user_id')::uuid,nullif(l->>'client_id','')::uuid,
  nullif(l->>'case_id','')::bigint,nullif(l->>'advisory_matter_id','')::uuid,(l->>'amount')::numeric,true,(l->>'amount')::numeric,
  coalesce(l->>'note',''),clock_timestamp(),auth.uid(),auth.uid());
 insert into public.finance_expense_audit(expense_id,event_type,actor_id,evidence_json)
 values(p_id,'legacy_bridged',auth.uid(),jsonb_build_object('legacy',l,'reason',btrim(p_reason),'no_payment_posted',true));
 return p_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.cancel_finance_accepted_quotation_engagement(p_fee_agreement_id uuid, p_reason text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_engagement public.finance_fee_agreements%rowtype;
  v_reason text := nullif(btrim(coalesce(p_reason, '')), '');
begin
  if not public.current_user_can_manage_finance_quotations() then
    raise exception 'Not allowed to cancel accepted quotation engagement';
  end if;
  if v_reason is null then raise exception 'Cancellation reason is required'; end if;
  if length(v_reason) > 2000 then raise exception 'Cancellation reason must not exceed 2000 characters'; end if;

  select *
  into v_engagement
  from public.finance_fee_agreements as engagement
  where engagement.id = p_fee_agreement_id
  for update;

  if v_engagement.id is null then raise exception 'Engagement not found'; end if;
  if v_engagement.engagement_basis <> 'accepted_quotation'
    or v_engagement.status <> 'engagement_confirmed'
  then
    raise exception 'Only a confirmed accepted quotation engagement can use this cancellation path';
  end if;
  if exists (
    select 1
    from public.finance_billing_plans as plan
    where plan.fee_agreement_id = v_engagement.id
      and plan.status <> 'cancelled'
  ) then
    raise exception 'Cancel the Billing Plan before cancelling this engagement';
  end if;

  update public.finance_fee_agreements
  set status = 'cancelled',
      cancelled_at = now(),
      cancelled_by_user_id = auth.uid(),
      cancel_reason = v_reason,
      updated_by_user_id = auth.uid(),
      updated_at = now()
  where id = v_engagement.id;

  return v_engagement.id;
end;
$function$

CREATE OR REPLACE FUNCTION public.cancel_finance_payout(p_id uuid, p_expected_version integer, p_acknowledged boolean)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare p public.finance_payouts%rowtype;
begin
 if not public.payout_can_manage() then raise exception 'PAYOUT_PERMISSION_DENIED'; end if;
 if p_acknowledged is distinct from true then raise exception 'PAYOUT_ACK_REQUIRED'; end if;
 perform pg_advisory_xact_lock(hashtextextended('payout_lifecycle',0));select * into p from public.finance_payouts where id=p_id for update;
 if p.status='cancelled' then return p.id; end if;
 if p.id is null or p.status<>'draft' or p.version is distinct from p_expected_version then raise exception 'PAYOUT_STALE'; end if;
 update public.finance_payouts set status='cancelled',version=version+1,cancelled_at=clock_timestamp(),cancelled_by=auth.uid(),updated_by=auth.uid(),updated_at=clock_timestamp() where id=p_id;
 insert into public.finance_payout_audit(payout_id,event_type,version,actor_id,evidence_json) values(p.id,'cancelled',p.version+1,auth.uid(),to_jsonb(p));return p.id;
end;
$function$

CREATE OR REPLACE FUNCTION public.clone_document_template_version(p_source_template_version_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_source public.document_template_versions%rowtype;
  v_template public.document_templates%rowtype;
  v_existing_draft_id uuid;
  v_new_version_id uuid;
  v_new_version_no integer;
  v_new_section_id uuid;
  v_new_group_id uuid;
  v_new_slot_id uuid;
  v_mapped_parent_id uuid;
  v_mapped_group_id uuid;
  v_mapped_default_slot_id uuid;
  v_section_map jsonb := '{}'::jsonb;
  v_group_map jsonb := '{}'::jsonb;
  v_slot_map jsonb := '{}'::jsonb;
  v_section public.document_template_sections%rowtype;
  v_group public.document_template_alternative_groups%rowtype;
  v_slot public.document_template_clause_slots%rowtype;
  v_binding public.document_template_variable_bindings%rowtype;
  v_source_section_count integer;
  v_source_group_count integer;
  v_source_slot_count integer;
  v_source_binding_count integer;
begin
  if auth.uid() is null or not public.current_user_can_manage_finance_quotations() then
    raise exception 'Not allowed to clone document template versions';
  end if;

  select tv.*
  into v_source
  from public.document_template_versions as tv
  where tv.id = p_source_template_version_id
  for share;

  if v_source.id is null then
    raise exception 'Source template version not found';
  end if;
  if v_source.status <> 'published' then
    raise exception 'Only Published template versions can be cloned';
  end if;

  -- This family lock serializes version-number allocation with the existing
  -- save_document_template_version_draft creation path.
  select t.*
  into v_template
  from public.document_templates as t
  where t.id = v_source.template_id
  for update;

  if v_template.id is null or v_template.status = 'retired' then
    raise exception 'Document template family is unavailable';
  end if;

  select tv.id
  into v_existing_draft_id
  from public.document_template_versions as tv
  where tv.template_id = v_source.template_id
    and tv.language_code = v_source.language_code
    and tv.status = 'draft'
    and tv.previous_version_id = v_source.id
    and tv.supersedes_version_id = v_source.id
  order by tv.version_no desc
  limit 1;

  -- Idempotent retry protection: return the same clone without overwriting it.
  if v_existing_draft_id is not null then
    return v_existing_draft_id;
  end if;

  if exists (
    select 1
    from public.document_template_versions as tv
    where tv.template_id = v_source.template_id
      and tv.language_code = v_source.language_code
      and tv.version_no > v_source.version_no
  ) then
    raise exception 'Only the latest Template version can be used as a clone source';
  end if;

  if exists (
    select 1
    from public.document_template_versions as tv
    where tv.template_id = v_source.template_id
      and tv.language_code = v_source.language_code
      and tv.status = 'draft'
  ) then
    raise exception 'Another Draft already exists for this template and language';
  end if;

  select coalesce(max(tv.version_no), 0) + 1
  into v_new_version_no
  from public.document_template_versions as tv
  where tv.template_id = v_source.template_id
    and tv.language_code = v_source.language_code;

  insert into public.document_template_versions (
    template_id,
    version_no,
    language_code,
    definition_json,
    status,
    effective_from,
    effective_to,
    previous_version_id,
    supersedes_version_id,
    change_summary_json,
    condition_rule_json,
    signature_requirements_json,
    renderer_schema_version,
    created_by_user_id,
    updated_by_user_id
  )
  values (
    v_source.template_id,
    v_new_version_no,
    v_source.language_code,
    coalesce(v_source.definition_json, '{}'::jsonb)
      || jsonb_build_object('inactive_shell', true, 'legal_wording_approved', false),
    'draft',
    v_source.effective_from,
    v_source.effective_to,
    v_source.id,
    v_source.id,
    coalesce(v_source.change_summary_json, '{}'::jsonb),
    v_source.condition_rule_json,
    v_source.signature_requirements_json,
    v_source.renderer_schema_version,
    auth.uid(),
    auth.uid()
  )
  returning id into v_new_version_id;

  -- Parents are cloned before children so hierarchy validation remains active.
  for v_section in
    select sec.*
    from public.document_template_sections as sec
    where sec.template_version_id = v_source.id
    order by sec.numbering_depth, sec.sort_order, sec.id
  loop
    v_mapped_parent_id := null;
    if v_section.parent_section_id is not null then
      v_mapped_parent_id := nullif(v_section_map ->> v_section.parent_section_id::text, '')::uuid;
      if v_mapped_parent_id is null then
        raise exception 'Unable to map parent section while cloning Template version';
      end if;
    end if;

    insert into public.document_template_sections (
      template_version_id, section_code, title, sort_order, parent_section_id,
      display_number, display_label, numbering_style, numbering_depth, section_kind,
      condition_rule_json, is_required, allow_custom_after, risk_level, metadata_json,
      created_by_user_id, updated_by_user_id
    )
    values (
      v_new_version_id, v_section.section_code, v_section.title, v_section.sort_order,
      v_mapped_parent_id, v_section.display_number, v_section.display_label,
      v_section.numbering_style, v_section.numbering_depth, v_section.section_kind,
      v_section.condition_rule_json, v_section.is_required, v_section.allow_custom_after,
      v_section.risk_level, v_section.metadata_json, auth.uid(), auth.uid()
    )
    returning id into v_new_section_id;

    v_section_map := v_section_map
      || jsonb_build_object(v_section.id::text, v_new_section_id::text);
  end loop;

  -- Alternative groups must exist before alternative slots can reference them.
  -- Default slot references are restored after all slots have been cloned.
  for v_group in
    select grp.*
    from public.document_template_alternative_groups as grp
    where grp.template_version_id = v_source.id
    order by grp.sort_order, grp.id
  loop
    insert into public.document_template_alternative_groups (
      template_version_id, group_code, title, minimum_selection, maximum_selection,
      selection_required, default_selected_slot_id, condition_rule_json, risk_level,
      sort_order, metadata_json, created_by_user_id, updated_by_user_id
    )
    values (
      v_new_version_id, v_group.group_code, v_group.title, v_group.minimum_selection,
      v_group.maximum_selection, v_group.selection_required, null,
      v_group.condition_rule_json, v_group.risk_level, v_group.sort_order,
      v_group.metadata_json, auth.uid(), auth.uid()
    )
    returning id into v_new_group_id;

    v_group_map := v_group_map
      || jsonb_build_object(v_group.id::text, v_new_group_id::text);
  end loop;

  for v_slot in
    select slot.*
    from public.document_template_clause_slots as slot
    join public.document_template_sections as sec on sec.id = slot.template_section_id
    where sec.template_version_id = v_source.id
    order by sec.sort_order, slot.numbering_depth, slot.sort_order, slot.id
  loop
    v_new_section_id := nullif(v_section_map ->> v_slot.template_section_id::text, '')::uuid;
    if v_new_section_id is null then
      raise exception 'Unable to map Template section while cloning clause slot';
    end if;

    v_mapped_parent_id := null;
    if v_slot.parent_slot_id is not null then
      v_mapped_parent_id := nullif(v_slot_map ->> v_slot.parent_slot_id::text, '')::uuid;
      if v_mapped_parent_id is null then
        raise exception 'Unable to map parent clause slot while cloning Template version';
      end if;
    end if;

    v_mapped_group_id := null;
    if v_slot.alternative_group_id is not null then
      v_mapped_group_id := nullif(v_group_map ->> v_slot.alternative_group_id::text, '')::uuid;
      if v_mapped_group_id is null then
        raise exception 'Unable to map alternative group while cloning Template version';
      end if;
    end if;

    insert into public.document_template_clause_slots (
      template_section_id, slot_code, clause_version_id, sort_order, parent_slot_id,
      display_number, display_label, numbering_style, numbering_depth, clause_type,
      alternative_group_id, condition_rule_json, is_required, allow_override,
      allow_suppress, allow_custom_after, risk_level, metadata_json,
      created_by_user_id, updated_by_user_id
    )
    values (
      v_new_section_id, v_slot.slot_code, v_slot.clause_version_id, v_slot.sort_order,
      v_mapped_parent_id, v_slot.display_number, v_slot.display_label,
      v_slot.numbering_style, v_slot.numbering_depth, v_slot.clause_type,
      v_mapped_group_id, v_slot.condition_rule_json, v_slot.is_required,
      v_slot.allow_override, v_slot.allow_suppress, v_slot.allow_custom_after,
      v_slot.risk_level, v_slot.metadata_json, auth.uid(), auth.uid()
    )
    returning id into v_new_slot_id;

    v_slot_map := v_slot_map
      || jsonb_build_object(v_slot.id::text, v_new_slot_id::text);
  end loop;

  for v_group in
    select grp.*
    from public.document_template_alternative_groups as grp
    where grp.template_version_id = v_source.id
      and grp.default_selected_slot_id is not null
    order by grp.sort_order, grp.id
  loop
    v_new_group_id := nullif(v_group_map ->> v_group.id::text, '')::uuid;
    v_mapped_default_slot_id := nullif(v_slot_map ->> v_group.default_selected_slot_id::text, '')::uuid;
    if v_new_group_id is null or v_mapped_default_slot_id is null then
      raise exception 'Unable to map default alternative selection while cloning Template version';
    end if;

    update public.document_template_alternative_groups as grp
    set default_selected_slot_id = v_mapped_default_slot_id,
        updated_by_user_id = auth.uid(),
        updated_at = now()
    where grp.id = v_new_group_id;
  end loop;

  for v_binding in
    select binding.*
    from public.document_template_variable_bindings as binding
    where binding.template_version_id = v_source.id
    order by binding.variable_definition_id, binding.id
  loop
    insert into public.document_template_variable_bindings (
      template_version_id, variable_definition_id, is_required,
      formatting_override_json, fallback_override, metadata_json,
      created_by_user_id, updated_by_user_id
    )
    values (
      v_new_version_id, v_binding.variable_definition_id, v_binding.is_required,
      v_binding.formatting_override_json, v_binding.fallback_override,
      v_binding.metadata_json, auth.uid(), auth.uid()
    );
  end loop;

  select count(*) into v_source_section_count
  from public.document_template_sections as sec
  where sec.template_version_id = v_source.id;
  select count(*) into v_source_group_count
  from public.document_template_alternative_groups as grp
  where grp.template_version_id = v_source.id;
  select count(*) into v_source_slot_count
  from public.document_template_clause_slots as slot
  join public.document_template_sections as sec on sec.id = slot.template_section_id
  where sec.template_version_id = v_source.id;
  select count(*) into v_source_binding_count
  from public.document_template_variable_bindings as binding
  where binding.template_version_id = v_source.id;

  if (select count(*) from public.document_template_sections as sec where sec.template_version_id = v_new_version_id) <> v_source_section_count
     or (select count(*) from public.document_template_alternative_groups as grp where grp.template_version_id = v_new_version_id) <> v_source_group_count
     or (select count(*) from public.document_template_clause_slots as slot join public.document_template_sections as sec on sec.id = slot.template_section_id where sec.template_version_id = v_new_version_id) <> v_source_slot_count
     or (select count(*) from public.document_template_variable_bindings as binding where binding.template_version_id = v_new_version_id) <> v_source_binding_count then
    raise exception 'Template version clone verification failed';
  end if;

  perform public.document_platform_audit(
    'template_version',
    v_new_version_id,
    'created_draft',
    jsonb_build_object(
      'source_template_version_id', v_source.id,
      'source_version_no', v_source.version_no,
      'new_version_no', v_new_version_no,
      'sections', v_source_section_count,
      'slots', v_source_slot_count,
      'alternative_groups', v_source_group_count,
      'variable_bindings', v_source_binding_count,
      'readiness_certification_reset', true
    )
  );

  return v_new_version_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.confirm_finance_expense_payout(p_id uuid, p_version integer, p_payee_version integer, p_destination uuid, p_acknowledged boolean)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare p public.finance_payouts%rowtype;c jsonb;canonical jsonb;recipient jsonb;claimant_reimbursement boolean;payee public.finance_payees%rowtype;dest public.finance_payee_destinations%rowtype;
 o public.finance_account_opening_balances%rowtype;snapshot jsonb;allocation uuid;cash uuid;ts timestamptz:=clock_timestamp();
begin
 select * into p from public.finance_payouts where id=p_id;
 if p.id is null or p.source_model<>'expense_v1' or not public.expense_account_allowed(p.bank_account_id,p.cash_location_id,'confirm_outflow')
 then raise exception 'EXPENSE_ACCOUNT_DENIED'; end if;
 if p_acknowledged is distinct from true then raise exception 'EXPENSE_ACTUAL_PAYMENT_ACK_REQUIRED'; end if;
 perform pg_advisory_xact_lock(hashtextextended('expense:'||(p.choices_json#>>'{0,expense_id}'),0));
 select * into p from public.finance_payouts where id=p_id for update;
 if not public.expense_account_allowed(p.bank_account_id,p.cash_location_id,'confirm_outflow') then raise exception 'EXPENSE_ACCOUNT_DENIED'; end if;
 if p.status='confirmed' then return p_id; end if;
 if p.status<>'draft' or p.version is distinct from p_version then raise exception 'EXPENSE_STALE'; end if;
 c:=p.choices_json->0;
 canonical:=public.expense_payout_choice((c->>'expense_id')::uuid,(c->>'actual_withholding')::boolean);
 if canonical is distinct from c then raise exception 'EXPENSE_PAYMENT_SOURCE_CHANGED'; end if;
 recipient:=c->'recipient';
 select * into payee from public.finance_payees where id=p.payee_id for share;
 select * into dest from public.finance_payee_destinations where payee_id=p.payee_id and is_active for share;
 if p.payee_id is not null and (payee.is_active is distinct from true or payee.version is distinct from p_payee_version
  or (payee.profile_id is not null and not exists(select 1 from public.user_profiles where id=payee.profile_id and active))) then raise exception 'PAYOUT_PAYEE_INVALID'; end if;
 -- Approved claimant reimbursement records actual company outflow, not a transfer instruction.
 -- Keep canonical source, identity, version, amount and acknowledgement checks above unchanged.
 claimant_reimbursement:=coalesce(c#>>'{expense,origin}'='employee_claim'
  and c#>>'{expense,status}'='accepted' and (c#>>'{expense,personally_paid}')::boolean
  and c#>>'{expense,claimant_id}'=payee.profile_id::text
  and c#>>'{settlement,mode}'='reimburse' and c#>>'{settlement,payee_id}'=p.payee_id::text
  and c->>'obligation_id' is not null and p.wht_amount=0,false);
 if recipient is null and not claimant_reimbursement and c->>'obligation_id' is not null and p.bank_account_id is not null and (dest.id is null or dest.id is distinct from p_destination)
 then raise exception 'PAYOUT_DESTINATION_REQUIRED'; end if;
 if recipient is null and p.wht_amount>0 and payee.tax_id is null then raise exception 'PAYOUT_TAX_ID_REQUIRED'; end if;
 perform pg_advisory_xact_lock(hashtextextended('finance_cash_cutover:THB',0));
 if not public.treasury_location_active(p.bank_account_id,p.cash_location_id) then raise exception 'EXPENSE_ACCOUNT_DENIED'; end if;
 select * into o from public.finance_account_opening_balances where bank_account_id is not distinct from p.bank_account_id
  and cash_location_id is not distinct from p.cash_location_id and currency='THB' and status='confirmed' for update;
 if o.id is null then raise exception 'FINANCE_CASH_OPENING_BALANCE_REQUIRED'; end if;
 if public.finance_bangkok_completed_day_end(p.paid_on)<=o.as_of then raise exception 'FINANCE_CASH_TRANSACTION_BEFORE_CUTOVER'; end if;
 snapshot:=jsonb_build_object('schema_version',2,'source_model','expense_v1','choices',p.choices_json,'payee',coalesce(recipient,to_jsonb(payee)),
  'destination',case when p.bank_account_id is not null then to_jsonb(dest) end,'opening',to_jsonb(o),
  'bank_account_id',p.bank_account_id,'cash_location_id',p.cash_location_id,'paid_on',p.paid_on,'currency',p.currency,
  'gross',p.gross_amount,'wht',p.wht_amount,'net',p.net_amount,'confirmed_by',auth.uid(),'actual_company_cash_moved',true);
 update public.finance_payouts set status='confirmed',version=version+1,confirmed_snapshot_json=snapshot,confirmed_at=ts,confirmed_by=auth.uid(),updated_at=ts,updated_by=auth.uid() where id=p_id;
 insert into public.finance_payout_allocations(payout_id,expense_id,expense_obligation_id,gross_amount,treatment,rate,wht_base,wht_amount,evidence_json)
 values(p_id,(c->>'expense_id')::uuid,(c->>'obligation_id')::uuid,p.gross_amount,c->>'treatment',(c->>'rate')::numeric,(c->>'wht_base')::numeric,p.wht_amount,c) returning id into allocation;
 if p.wht_amount>0 then
  insert into public.finance_outgoing_wht_obligations(payout_source_id,source_line_id,source_fingerprint,payee_json,gross_base,explicit_treatment,explicit_rate,withheld_amount,withheld_on,period_month,currency,evidence_json)
  values(p_id,allocation,md5(c::text),coalesce(recipient,to_jsonb(payee)),(c->>'wht_base')::numeric,'withhold',(c->>'rate')::numeric,p.wht_amount,p.paid_on,date_trunc('month',p.paid_on)::date,'THB',c);
 end if;
 insert into public.finance_cash_transactions(occurred_at,direction,transaction_type,bank_account_id,cash_location_id,cash_amount,currency,status,source_payout_id,reference_no,description,created_by_user_id,updated_by_user_id,confirmed_at,confirmed_by_user_id)
 values(public.finance_bangkok_completed_day_end(p.paid_on),'outflow','other',p.bank_account_id,p.cash_location_id,p.net_amount,'THB','confirmed',p.id,upper(left(p.id::text,8)),'Expense payout',auth.uid(),auth.uid(),ts,auth.uid()) returning id into cash;
 perform public.record_finance_cash_transaction_audit_event(cash,'confirmed',jsonb_build_object('payout_id',p.id,'payout',snapshot,'outgoing_wht_is_not_cash_outflow',true));
 insert into public.finance_payout_audit(payout_id,event_type,version,actor_id,evidence_json) values(p.id,'confirmed',p.version+1,auth.uid(),snapshot);
 insert into public.finance_expense_audit(expense_id,event_type,actor_id,evidence_json) values((c->>'expense_id')::uuid,'payment_confirmed',auth.uid(),snapshot);
 return p_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.confirm_finance_payout(p_id uuid, p_expected_version integer, p_expected_payee_version integer, p_expected_destination_id uuid, p_acknowledged boolean)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
 if exists(select 1 from public.finance_payouts where id=p_id and source_model='expense_v1') then
  return public.confirm_finance_expense_payout(p_id,p_expected_version,p_expected_payee_version,p_expected_destination_id,p_acknowledged);
 end if;
 return public.confirm_finance_payout_before_expense(p_id,p_expected_version,p_expected_payee_version,p_expected_destination_id,p_acknowledged);
end;
$function$

CREATE OR REPLACE FUNCTION public.create_finance_tax_correction_draft(p_request_id uuid, p_tax_invoice_id uuid, p_combined_id uuid, p_mode text, p_reason text, p_legal_basis text, p_evidence_reference text, p_issue_date date, p_adjustment_date date, p_lines jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare src jsonb; req jsonb; draft jsonb; prior public.finance_tax_document_corrections%rowtype; cid uuid:=gen_random_uuid();
 line jsonb; original public.finance_tax_invoice_items%rowtype; delta numeric; dv numeric; pb numeric; pv numeric;
 lines jsonb:='[]'; buyer jsonb; customer jsonb; sign integer; source_id uuid; totals jsonb;
begin
 if public.tax_correction_authorized(p_combined_id is not null,'manage') is distinct from true then raise exception 'TAX_CORRECTION_PERMISSION_DENIED'; end if;
 if p_request_id is null then raise exception 'TAX_CORRECTION_REQUEST_REQUIRED'; end if;
 perform 1 from public.finance_tax_invoices where id=p_tax_invoice_id for update;
 req:=jsonb_build_object('tax',p_tax_invoice_id,'combined',p_combined_id,'mode',p_mode,'reason',p_reason,'basis',p_legal_basis,
   'evidence',p_evidence_reference,'issue_date',p_issue_date,'adjustment_date',p_adjustment_date,'lines',p_lines);
 select * into prior from public.finance_tax_document_corrections where request_id=p_request_id;
 if found then if prior.request_json is distinct from req then raise exception 'TAX_CORRECTION_IDEMPOTENCY_CONFLICT'; end if; return prior.id; end if;
 src:=public.tax_correction_source(p_tax_invoice_id,p_combined_id); source_id:=(src->>'source_correction_id')::uuid;
 if p_mode is null or p_mode not in ('credit_note','debit_note','cancel_and_reissue','replacement_copy')
   or nullif(btrim(p_reason),'') is null or length(btrim(p_reason))<5
   or nullif(btrim(p_evidence_reference),'') is null or length(btrim(p_evidence_reference))<5
 then raise exception 'TAX_CORRECTION_REASON_EVIDENCE_REQUIRED'; end if;
 if p_issue_date is null or p_adjustment_date is null or p_issue_date>(now() at time zone 'Asia/Bangkok')::date
   or p_adjustment_date>p_issue_date or p_adjustment_date<(src->>'document_date')::date
 then raise exception 'TAX_CORRECTION_DATES_INVALID'; end if;
 if p_mode in ('credit_note','debit_note') and p_issue_date>=(date_trunc('month',p_adjustment_date)+interval '2 months')::date
 then raise exception 'TAX_CORRECTION_ADJUSTMENT_PERIOD_REVIEW_REQUIRED'; end if;
 if p_legal_basis is null or not(case p_mode
   when 'credit_note' then p_legal_basis in ('service_overcharge','service_reduction','service_cancelled')
   when 'debit_note' then p_legal_basis in ('service_undercharge','additional_service')
   when 'cancel_and_reissue' then p_legal_basis='documentary_identity_error'
   when 'replacement_copy' then p_legal_basis in ('lost','destroyed','materially_damaged') else false end)
 then raise exception 'TAX_CORRECTION_MODE_BASIS_INCOMPATIBLE'; end if;
 if jsonb_typeof(p_lines) is distinct from 'array' then raise exception 'TAX_CORRECTION_LINES_REQUIRED'; end if;
 if exists(select 1 from public.finance_tax_document_corrections where original_tax_invoice_id=p_tax_invoice_id and status in ('draft','approved'))
 then raise exception 'TAX_CORRECTION_OPEN_CASE_EXISTS'; end if;
 if p_mode in ('credit_note','debit_note') then
   if jsonb_array_length(p_lines)=0 then raise exception 'TAX_CORRECTION_LINES_REQUIRED'; end if;
   sign:=case when p_mode='credit_note' then -1 else 1 end;
   for line in select value from jsonb_array_elements(p_lines) loop
     if jsonb_typeof(line) is distinct from 'object' or line-array['item_id','base_change']<>'{}'::jsonb then raise exception 'TAX_CORRECTION_LINE_INVALID'; end if;
     select * into original from public.finance_tax_invoice_items where id=(line->>'item_id')::uuid and tax_invoice_id=p_tax_invoice_id;
     if not found or exists(select 1 from jsonb_array_elements(lines) l where l->>'item_id'=original.id::text)
     then raise exception 'TAX_CORRECTION_SOURCE_COVERAGE_INVALID'; end if;
     delta:=(line->>'base_change')::numeric;
     if delta is null or delta::text in ('NaN','Infinity','-Infinity') or delta<=0 or round(delta,2)<>delta then raise exception 'TAX_CORRECTION_AMOUNT_INVALID'; end if;
     select original.amount_before_vat+coalesce(sum(case x.correction_mode when 'credit_note' then -l.base_change else l.base_change end),0),
       original.vat_amount+coalesce(sum(case x.correction_mode when 'credit_note' then -l.vat_change else l.vat_change end),0)
     into pb,pv from public.finance_tax_correction_lines l join public.finance_tax_document_corrections x on x.id=l.correction_id
     where l.original_tax_invoice_item_id=original.id and x.status='issued';
     -- Credit reductions cannot exceed the effective tax position; debit increases have no original-base cap.
     if sign=-1 and delta>pb
     then raise exception 'TAX_CORRECTION_SOURCE_COVERAGE_EXCEEDED'; end if;
     dv:=case when sign=-1 and delta=pb then pv else round(delta*(original.source_snapshot_json->>'vat_rate')::numeric/100,2) end;
     if dv is null or dv<0 or (sign=-1 and dv>pv) then raise exception 'TAX_CORRECTION_VAT_INVALID'; end if;
     lines:=lines||jsonb_build_array(jsonb_build_object('item_id',original.id,'source',original.source_snapshot_json,
       'original_base',original.amount_before_vat,'original_vat',original.vat_amount,'previous_base',pb,'previous_vat',pv,
       'base_change',delta,'vat_change',dv,'resulting_base',pb+sign*delta,'resulting_vat',pv+sign*dv));
   end loop;
 elsif jsonb_array_length(p_lines)<>0 then raise exception 'TAX_CORRECTION_DOCUMENTARY_AMOUNTS_BLOCKED'; end if;
 draft:=src||jsonb_build_object('schema_version',1,'correction_mode',p_mode,'reason',btrim(p_reason),'legal_basis',p_legal_basis,
   'evidence_reference',btrim(p_evidence_reference),'issue_date',p_issue_date,'adjustment_date',p_adjustment_date,'lines',lines);
 select jsonb_build_object('original_base',sum(amount_before_vat),'original_vat',sum(vat_amount)) into totals
 from public.finance_tax_invoice_items where tax_invoice_id=p_tax_invoice_id;
 select totals||jsonb_build_object('previous_base',(totals->>'original_base')::numeric+coalesce(sum(case x.correction_mode when 'credit_note' then -l.base_change else l.base_change end),0),
   'previous_vat',(totals->>'original_vat')::numeric+coalesce(sum(case x.correction_mode when 'credit_note' then -l.vat_change else l.vat_change end),0)) into totals
 from public.finance_tax_correction_lines l join public.finance_tax_document_corrections x on x.id=l.correction_id
 where x.original_tax_invoice_id=p_tax_invoice_id and x.status='issued';
 select totals||jsonb_build_object('base_change',coalesce(sum((l->>'base_change')::numeric),0),
   'vat_change',coalesce(sum((l->>'vat_change')::numeric),0),
   'resulting_base',(totals->>'previous_base')::numeric+coalesce(sign,0)*coalesce(sum((l->>'base_change')::numeric),0),
   'resulting_vat',(totals->>'previous_vat')::numeric+coalesce(sign,0)*coalesce(sum((l->>'vat_change')::numeric),0)) into totals from jsonb_array_elements(lines) l;
 draft:=draft||jsonb_build_object('totals',totals);
 if p_mode='cancel_and_reissue' then
   buyer:=public.get_finance_customer_tax_profile((src #>> '{tax,customer,id}')::uuid);
   buyer:=jsonb_build_object('schema_version',1,'status',buyer->'status','profile',buyer->'profile');
   if buyer->>'status' is distinct from 'verified' then raise exception 'TAX_CORRECTION_REVIEWED_BUYER_REQUIRED'; end if;
   customer:=(src #> '{tax,customer}')||(buyer #> '{profile,identity_snapshot_json}')||jsonb_build_object(
     'vat_registered',buyer #> '{profile,vat_registered}','branch_type',buyer #> '{profile,branch_type}',
     'branch_code',buyer #> '{profile,branch_code}','supplemental_evidence',buyer #> '{profile,identity_evidence}');
   if nullif(btrim(customer->>'name'),'') is null or nullif(btrim(customer->>'address'),'') is null
     or customer->>'tax_id' !~ '^[0-9]{13}$' then raise exception 'TAX_CORRECTION_REVIEWED_BUYER_REQUIRED'; end if;
   draft:=jsonb_set(draft,'{tax}',(src->'tax')||jsonb_build_object('customer',customer,'buyer_tax_profile',buyer));
   if p_combined_id is not null then draft:=jsonb_set(draft,'{receipt}',(src->'receipt')||jsonb_build_object('customer',customer)); end if;
 end if;
 insert into public.finance_tax_document_corrections(id,request_id,original_tax_invoice_id,original_combined_document_id,original_receipt_id,
   invoice_id,payment_id,direct_money_receipt_id,source_correction_id,correction_mode,reason,legal_basis,evidence_reference,issue_date,adjustment_date,
   source_snapshot_json,draft_snapshot_json,request_json,created_by_user_id)
 values(cid,p_request_id,p_tax_invoice_id,p_combined_id,(src->>'receipt_id')::uuid,(src->>'invoice_id')::uuid,(src->>'payment_id')::uuid,(src->>'direct_money_receipt_id')::uuid,
   source_id,p_mode,btrim(p_reason),p_legal_basis,btrim(p_evidence_reference),p_issue_date,p_adjustment_date,src,draft,req,auth.uid());
 insert into public.finance_tax_correction_lines(correction_id,original_tax_invoice_item_id,base_change,vat_change,previous_base,previous_vat,resulting_base,resulting_vat,source_snapshot_json)
 select cid,(l->>'item_id')::uuid,(l->>'base_change')::numeric,(l->>'vat_change')::numeric,(l->>'previous_base')::numeric,
   (l->>'previous_vat')::numeric,(l->>'resulting_base')::numeric,(l->>'resulting_vat')::numeric,l->'source' from jsonb_array_elements(lines) l;
 insert into public.finance_tax_correction_audit_events(correction_id,event_type,event_payload_json,actor_user_id)
 values(cid,'draft_created',jsonb_build_object('reason',p_reason,'legal_basis',p_legal_basis,'evidence_reference',p_evidence_reference,'lines',lines,'number_allocated',false),auth.uid());
 return cid;
end;
$function$

CREATE OR REPLACE FUNCTION public.create_finance_tax_filing_review(p_id uuid, p_month date, p_type text, p_expected_fingerprint text, p_channel text, p_expected_deadline jsonb, p_override jsonb DEFAULT NULL::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare s jsonb; coverage jsonb; deadline jsonb; due date; due_ref text; f public.finance_tax_filings%rowtype; r jsonb;
begin
 if public.tax_filing_can_manage() is distinct from true then raise exception 'TAX_FILING_PERMISSION_DENIED'; end if;
 if p_override is not null and not public.money_allocation_admin() then raise exception 'TAX_DEADLINE_ADMIN_REQUIRED'; end if;
 perform pg_advisory_xact_lock(hashtextextended('payout_lifecycle',0)); perform pg_advisory_xact_lock(500050); perform pg_advisory_xact_lock(500052); perform pg_advisory_xact_lock(500054);
 select * into f from public.finance_tax_filings where id=p_id;
 if found then
  if f.period_month is distinct from p_month or f.filing_type is distinct from p_type or f.source_fingerprint is distinct from p_expected_fingerprint
   or f.deadline_snapshot_json->>'channel' is distinct from p_channel or f.deadline_snapshot_json->'reviewed' is distinct from p_expected_deadline
   or f.deadline_snapshot_json->'override_input' is distinct from coalesce(p_override,'null'::jsonb)
   then raise exception 'TAX_FILING_IDEMPOTENCY_CONFLICT'; end if;
  return p_id;
 end if;
 if exists(select 1 from public.finance_tax_filings where period_month=p_month and filing_type=p_type and status<>'cancelled') then raise exception 'TAX_FILING_ALREADY_EXISTS'; end if;
 deadline:=public.tax_filing_deadline(p_month,p_type,p_channel);
 if deadline is distinct from p_expected_deadline then raise exception 'TAX_DEADLINE_SOURCE_CHANGED'; end if;
 deadline:=deadline||jsonb_build_object('reviewed',deadline,'override_input',p_override);
 if p_override is not null then
  if jsonb_typeof(p_override) is distinct from 'object' or nullif(btrim(p_override->>'reason'),'') is null
   or nullif(btrim(p_override->>'reference'),'') is null or (p_override->>'due_date')::date is null
   or (p_override->>'due_date')::date<p_month or length(p_override::text)>4000 then raise exception 'TAX_DEADLINE_OVERRIDE_INVALID'; end if;
  deadline:=deadline||jsonb_build_object('status','admin_override','due_date',(p_override->>'due_date')::date,'override_actor',auth.uid(),'override_at',now());
 end if;
 due:=(deadline->>'due_date')::date;
 due_ref:=case when due is null then null when p_override is not null then left(p_override->>'reference',2000) else left(deadline#>>'{rule,spec,reference}',2000) end;
 s:=public.tax_filing_pool(p_month,p_type);
 if md5(s::text) is distinct from p_expected_fingerprint then raise exception 'TAX_FILING_SOURCE_CHANGED'; end if;
 coverage:=case when s->>'schema_version'='2' then s->'allocation_coverage' else s end;
 insert into public.finance_tax_filings(id,period_month,filing_type,due_date,due_date_evidence,deadline_snapshot_json,source_fingerprint,source_snapshot_json,base_amount,tax_amount,created_by)
 values(p_id,p_month,p_type,due,due_ref,deadline,md5(s::text),s,(coverage->>'base_amount')::numeric,(s->>'tax_amount')::numeric,auth.uid());
 for r in select value from jsonb_array_elements(coverage->'sources') loop
  insert into public.finance_tax_filing_allocations(filing_id,tax_fact_id,outgoing_wht_id,economic_key,source_fingerprint,evidence_json)
  values(p_id,(r->>'tax_fact_id')::uuid,(r->>'outgoing_wht_id')::uuid,r->>'economic_key',r->>'fingerprint',r);
 end loop;
 insert into public.finance_tax_filing_audit(filing_id,event_type,version,actor_id,evidence_json)
 select id,'created',version,auth.uid(),to_jsonb(x) from public.finance_tax_filings x where id=p_id;
 return p_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.create_finance_tax_remittance(p_id uuid, p_filing_id uuid, p_bank uuid, p_cash uuid, p_paid_on date, p_reference text, p_evidence text, p_expected_account jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare f public.finance_tax_filings%rowtype;r public.finance_tax_remittances%rowtype; account jsonb;
begin
 if public.tax_filing_can_remit() is distinct from true then raise exception 'TAX_FILING_PERMISSION_DENIED'; end if;
 perform pg_advisory_xact_lock(500052); perform pg_advisory_xact_lock(hashtextextended('finance_cash_cutover:THB',0));
 select * into r from public.finance_tax_remittances where id=p_id;
 if found then
  if r.filing_id is distinct from p_filing_id or r.bank_account_id is distinct from p_bank or r.cash_location_id is distinct from p_cash or r.paid_on is distinct from p_paid_on
   or r.external_reference is distinct from btrim(p_reference) or r.payment_evidence is distinct from btrim(p_evidence) or r.draft_snapshot_json->'account' is distinct from p_expected_account then raise exception 'TAX_FILING_IDEMPOTENCY_CONFLICT'; end if;
  return r.id;
 end if;
 select * into f from public.finance_tax_filings where id=p_filing_id;
 if f.id is null or f.status<>'filed' or coalesce(f.tax_amount,0)<=0 then raise exception 'TAX_FILING_PAYMENT_NOT_REQUIRED'; end if;
 if exists(select 1 from public.finance_tax_remittances where filing_id=p_filing_id and status<>'cancelled') then raise exception 'TAX_FILING_ALREADY_EXISTS'; end if;
 if p_paid_on is null or p_paid_on<f.filed_on or p_paid_on>(now() at time zone 'Asia/Bangkok')::date then raise exception 'TAX_FILING_PAYMENT_DATE_INVALID'; end if;
 account:=public.tax_filing_account(p_bank,p_cash);
 if account is distinct from p_expected_account then raise exception 'TAX_FILING_ACCOUNT_CHANGED'; end if;
 insert into public.finance_tax_remittances(id,filing_id,amount,paid_on,bank_account_id,cash_location_id,external_reference,payment_evidence,draft_snapshot_json,created_by)
 values(p_id,f.id,f.tax_amount,p_paid_on,p_bank,p_cash,btrim(p_reference),btrim(p_evidence),jsonb_build_object('schema_version',1,'filing',f.filed_snapshot_json,'account',account,'amount_due',f.tax_amount),auth.uid());
 insert into public.finance_tax_remittance_audit(remittance_id,event_type,version,actor_id,evidence_json)
 select id,'created',version,auth.uid(),to_jsonb(x) from public.finance_tax_remittances x where id=p_id;
 return p_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.decide_finance_expense_settlement(p_id uuid, p_expense uuid, p_mode text, p_payee uuid, p_amount numeric, p_due_on date, p_reason text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare e public.finance_expenses%rowtype;s public.finance_expense_settlements%rowtype; effective numeric;
begin
 if not public.expense_can_manage() then raise exception 'EXPENSE_PERMISSION_DENIED'; end if;
 perform pg_advisory_xact_lock(hashtextextended('expense:'||p_expense,0));select * into e from public.finance_expenses where id=p_expense for update;
 if e.status is distinct from 'accepted' then raise exception 'EXPENSE_ACCEPTED_REQUIRED'; end if;
 p_reason:=coalesce(btrim(p_reason),'');
 if (e.origin<>'company_purchase' or e.personally_paid or p_mode in ('reimburse','no_reimbursement')) and p_reason=''
 then raise exception 'EXPENSE_REASON_REQUIRED';end if;
 if public.company_purchase_request_declaration(p_expense) is not null and
  (p_mode is distinct from 'supplier_unpaid' or p_payee is not null or public.company_purchase_request_recipient(p_expense) is null)
 then raise exception 'EXPENSE_REQUEST_REVIEW_REQUIRED';end if;
 effective:=public.company_expense_reviewed_gross(p_expense);
 if p_mode in ('company_bank','company_cash') and exists(select 1 from public.finance_expense_tax_reviews r
  where r.expense_id=e.id and r.request_json->>'schema_version'='2' and r.wht_state='withhold'
   and not exists(select 1 from public.finance_expense_tax_reviews n where n.supersedes_id=r.id))
  and p_payee is distinct from e.supplier_payee_id then raise exception 'EXPENSE_PAYEE_INVALID';end if;
 select * into s from public.finance_expense_settlements where expense_id=p_expense;
 if s.id is not null then
  if s.id=p_id and s.mode=p_mode and s.payee_id is not distinct from p_payee and s.amount=p_amount and s.reason=btrim(p_reason) then return s.id; end if;
  raise exception 'EXPENSE_SETTLEMENT_ALREADY_DECIDED';
 end if;
 if p_mode is null or p_mode='undecided' or p_amount is null or p_amount<>round(p_amount,2) or p_amount>effective
  or (p_mode in ('company_bank','company_cash','supplier_unpaid') and (e.personally_paid or p_amount<>effective))
  or (p_mode in ('reimburse','no_reimbursement') and not e.personally_paid)
  or (p_mode='reimburse' and not exists(select 1 from public.finance_payees where id=p_payee and profile_id=e.claimant_id and is_active))
  or (p_mode='supplier_unpaid' and ((e.supplier_payee_id is not null and e.supplier_payee_id is distinct from p_payee) or (not (p_payee is null and public.company_purchase_request_recipient(p_expense) is not null) and not exists(select 1 from public.finance_payees where id=p_payee and is_active))))
 then raise exception 'EXPENSE_SETTLEMENT_INVALID'; end if;
 insert into public.finance_expense_settlements(id,expense_id,mode,payee_id,amount,reason,created_by)
 values(p_id,p_expense,p_mode,p_payee,p_amount,btrim(p_reason),auth.uid()) returning * into s;
 if p_mode in ('supplier_unpaid','reimburse') then
  insert into public.finance_expense_obligations(id,expense_id,settlement_id,source_type,payee_id,gross_amount,due_on,created_by)
  values(p_id,p_expense,p_id,case when p_mode='reimburse' then 'employee_reimbursement' else 'supplier_payable' end,p_payee,p_amount,p_due_on,auth.uid());
 end if;
 insert into public.finance_expense_audit(expense_id,event_type,actor_id,evidence_json) values(p_expense,'settlement_decided',auth.uid(),to_jsonb(s));
 return p_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.delete_finance_authorized_signer(p_signer_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_signer public.finance_authorized_signers%rowtype;
begin
  if not public.current_user_can_manage_finance_quotations() then
    raise exception 'Not allowed to delete authorized signer';
  end if;

  select * into v_signer
  from public.finance_authorized_signers
  where id = p_signer_id
  for update;

  if v_signer.id is null then
    raise exception 'Authorized signer not found';
  end if;

  if v_signer.is_default then
    raise exception 'กรุณาตั้งผู้ลงนามเริ่มต้นคนใหม่ก่อนลบรายนี้';
  end if;

  if exists (
    select 1
    from public.finance_quotations q
    where q.authorized_signer_key = v_signer.signer_key
      or q.authorized_signer_name = v_signer.display_name
      or q.authorized_signer_email = v_signer.email
      or q.document_data_snapshot_json -> 'authorized_signer' ->> 'key' = v_signer.signer_key
  ) then
    raise exception 'ผู้ลงนามรายนี้เคยถูกใช้ในเอกสารแล้ว กรุณาปิดใช้งานแทนการลบ';
  end if;

  delete from public.finance_authorized_signers where id = v_signer.id;
  return coalesce(v_signer.signature_storage_path, '');
end;
$function$

CREATE OR REPLACE FUNCTION public.expense_payout_choice(p_expense uuid, p_actual_wht boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare e public.finance_expenses%rowtype;s public.finance_expense_settlements%rowtype;o public.finance_expense_obligations%rowtype;
 r public.finance_expense_tax_reviews%rowtype; gross numeric;rate numeric:=0;base numeric:=0;wht numeric:=0;
begin
 select * into strict e from public.finance_expenses where id=p_expense;
 select * into s from public.finance_expense_settlements where expense_id=p_expense;
 select * into o from public.finance_expense_obligations where expense_id=p_expense;
 select * into r from public.finance_expense_tax_reviews where expense_id=p_expense order by revision desc limit 1;
 if s.id is null or s.mode in ('undecided','no_reimbursement') or e.status not in ('submitted','accepted')
  or (o.id is not null and e.status<>'accepted')
  or exists(select 1 from public.finance_expense_obligation_waivers where obligation_id=o.id)
  or exists(select 1 from public.finance_payout_allocations where expense_id=p_expense) then raise exception 'EXPENSE_PAYMENT_UNAVAILABLE'; end if;
 gross:=s.amount;
 if e.origin='company_purchase' and not e.personally_paid and e.status='accepted' then
  if r.id is null or r.wht_state='pending' then raise exception 'EXPENSE_WHT_DECISION_REQUIRED';end if;
  if r.request_json->>'schema_version'='2' and p_actual_wht is distinct from (r.wht_state='withhold')
  then raise exception 'EXPENSE_WHT_ACTUAL_FACTS_REQUIRED';end if;
 end if;
 if p_actual_wht is null then raise exception 'EXPENSE_ACTUAL_WITHHOLDING_REQUIRED'; end if;
 if p_actual_wht then
  if s.mode='reimburse' or e.personally_paid or r.wht_state is distinct from 'withhold' or r.wht_exception
   or (public.company_purchase_request_recipient(p_expense) is null and not exists(select 1 from public.finance_payees where id=s.payee_id and is_active and tax_id is not null))
  then raise exception 'EXPENSE_WHT_ACTUAL_FACTS_REQUIRED'; end if;
  base:=r.wht_base;rate:=r.wht_rate;wht:=round(base*rate/100,2);
 end if;
 return jsonb_build_object('expense_id',e.id,'obligation_id',o.id,'payee_id',s.payee_id,'settlement',to_jsonb(s),
  'expense',to_jsonb(e),'tax_review',to_jsonb(r),'obligation',to_jsonb(o),'actual_withholding',p_actual_wht,
  'gross',gross,'wht_base',base,'rate',rate,'wht',wht,'treatment',case when p_actual_wht then 'withhold' else 'none' end)||case when public.company_purchase_request_recipient(p_expense) is not null then
  jsonb_build_object('recipient',jsonb_build_object('legal_name',public.company_purchase_request_recipient(p_expense),'identity_source','company_purchase_request','expense_id',p_expense)) else '{}'::jsonb end;
end;
$function$

