CREATE OR REPLACE FUNCTION public.get_finance_expenses(p_id uuid DEFAULT NULL::uuid, p_claims boolean DEFAULT false, p_offset integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
 if auth.uid() is null or not exists(select 1 from public.user_profiles where id=auth.uid() and active) then raise exception 'EXPENSE_PERMISSION_DENIED'; end if;
 if p_offset is null or p_offset<0 or p_offset>100000 then raise exception 'EXPENSE_INPUT_INVALID'; end if;
 if p_id is not null then return public.get_finance_expenses_before_requests(p_id,p_claims,p_offset); end if;
 return jsonb_build_object('access',public.get_finance_expense_access(),'accounts',public.get_finance_expense_accounts(),
  'rows',(select coalesce(jsonb_agg(public.expense_document(x.id) order by x.created_at desc,x.id),'[]') from
   (select e.id,e.created_at from public.finance_expenses e where public.expense_can_read(e.id) and (not p_claims or e.origin in ('employee_claim','legacy_claim'))
    and not exists(select 1 from public.finance_expense_request_items i where i.expense_id=e.id and (not i.active or public.expense_request_can_read(i.request_id))) order by e.created_at desc,e.id limit 50 offset p_offset) x),
  'has_next',(select count(*)>p_offset+50 from public.finance_expenses e where public.expense_can_read(e.id) and (not p_claims or e.origin in ('employee_claim','legacy_claim'))
    and not exists(select 1 from public.finance_expense_request_items i where i.expense_id=e.id and (not i.active or public.expense_request_can_read(i.request_id)))));
end;
$function$

CREATE OR REPLACE FUNCTION public.get_finance_payout_workspace_before_expense(p_payee_id uuid, p_payout_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare result jsonb;
begin
 if not public.current_user_can_view_finance_payments() then raise exception 'PAYOUT_PERMISSION_DENIED'; end if;
 if p_payout_id is not null and not exists(select 1 from public.finance_payouts where id=p_payout_id and payee_id=p_payee_id) then raise exception 'PAYOUT_INPUT_INVALID'; end if;
 select jsonb_build_object('can_manage',public.payout_can_manage(),'payees',public.get_finance_payees(),
  'payout',(select to_jsonb(p) from public.finance_payouts p where id=p_payout_id),
  'components',(select coalesce(jsonb_agg(to_jsonb(e) order by e.finalized_at,e.id),'[]') from public.finance_payable_entitlements e where e.recipient_id=p_payee_id and e.status='open'
   and not exists(select 1 from public.finance_payout_allocations a where a.entitlement_id=e.id)),
  'accounts',case when public.current_user_can_view_finance_cash_transactions() then (public.get_finance_treasury()->'accounts') else '[]'::jsonb end,
  'history',(select coalesce(jsonb_agg(jsonb_build_object('id',p.id,'paid_on',p.paid_on,'status',p.status,'gross',p.gross_amount,'wht',p.wht_amount,'net',p.net_amount,'bank_account_id',p.bank_account_id,'cash_location_id',p.cash_location_id) order by p.created_at desc,p.id),'[]') from public.finance_payouts p where p.payee_id=p_payee_id)) into result;
 -- Non-managers receive masked documentary identity, not raw bank/tax snapshots.
 if not public.payout_can_manage() and result->'payout'<>'null'::jsonb then
  result:=jsonb_set(result,'{payout,confirmed_snapshot_json,payee,tax_id}',to_jsonb('*********'::text),false);
  result:=jsonb_set(result,'{payout,confirmed_snapshot_json,destination,account_number}',to_jsonb('********'::text),false);
  result:=jsonb_set(result,'{payout,confirmed_snapshot_json,account,account_number}',to_jsonb('********'::text),false);
 end if;
 return result;
end;
$function$

CREATE OR REPLACE FUNCTION public.get_finance_payout_workspace(p_payee_id uuid, p_payout_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare result jsonb;
begin
 if not public.current_user_can_view_finance_payments() then raise exception 'PAYOUT_PERMISSION_DENIED'; end if;
 if exists(select 1 from public.finance_payouts where id=p_payout_id and source_model<>'revenue_distribution_v1')
  then raise exception 'PAYOUT_SOURCE_MODEL_MISMATCH'; end if;
 result:=public.get_finance_payout_workspace_before_expense(p_payee_id,p_payout_id);
 return jsonb_set(result,'{history}',(select coalesce(jsonb_agg(h.value order by h.ordinality),'[]')
  from jsonb_array_elements(result->'history') with ordinality h
  join public.finance_payouts p on p.id=(h.value->>'id')::uuid where p.source_model='revenue_distribution_v1'));
end;
$function$

CREATE OR REPLACE FUNCTION public.get_finance_tax_filings(p_month date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare pools jsonb:='[]'; s jsonb; kind text; filings jsonb; accounts jsonb;
begin
 if public.tax_position_can_view() is distinct from true then raise exception 'TAX_FILING_PERMISSION_DENIED'; end if;
 foreach kind in array array['vat','wht_natural','wht_juristic'] loop
  s:=public.tax_filing_pool(p_month,kind);pools:=pools||jsonb_build_array(s||jsonb_build_object('fingerprint',md5(s::text)));
 end loop;
 select coalesce(jsonb_agg(to_jsonb(f)||jsonb_build_object('source_changed',f.source_fingerprint<>md5(public.tax_filing_pool(f.period_month,f.filing_type)::text),
  'remittance',(select to_jsonb(r) from public.finance_tax_remittances r where r.filing_id=f.id and r.status<>'cancelled'),
  'audit',(select coalesce(jsonb_agg(to_jsonb(a) order by a.version),'[]') from public.finance_tax_filing_audit a where a.filing_id=f.id),
  'payment_history',(select coalesce(jsonb_agg(to_jsonb(r)||jsonb_build_object('audit',(select jsonb_agg(to_jsonb(a) order by a.version) from public.finance_tax_remittance_audit a where a.remittance_id=r.id)) order by r.created_at,r.id),'[]') from public.finance_tax_remittances r where r.filing_id=f.id)) order by f.created_at desc,f.id),'[]')
 into filings from public.finance_tax_filings f where f.period_month=p_month;
 select coalesce(jsonb_agg(to_jsonb(a) order by a.kind,a.name_en),'[]') into accounts from public.finance_treasury_balances a
 where public.treasury_can_view(a.bank_account_id,a.cash_location_id);
 return jsonb_build_object('can_manage',public.tax_filing_can_manage(),'can_remit',public.tax_filing_can_remit(),'period_month',p_month,
  'pools',pools,'filings',filings,'accounts',accounts,'incoming_wht_credit',(select coalesce(sum(f.tax_amount),0) from public.finance_tax_position_facts f
   where f.period_month=p_month and f.tax_kind='incoming_wht' and not exists(select 1 from public.finance_tax_source_revisions v where v.supersedes_id=f.revision_id)),
  'history',(select coalesce(jsonb_agg(to_jsonb(x) order by x.period_month desc,x.created_at desc),'[]') from (select id,period_month,filing_type,status,tax_amount,filed_on,external_reference,created_at,
   case when status='filed' and tax_amount=0 then 'no_payment_required' when exists(select 1 from public.finance_tax_remittances r where r.filing_id=f.id and status='confirmed') then 'remitted' when status='filed' then 'awaiting_payment' else status end as payment_state
   from public.finance_tax_filings f order by period_month desc,created_at desc limit 20) x));
end;
$function$

