$function$

CREATE OR REPLACE FUNCTION public.issue_finance_tax_correction(p_id uuid, p_reviewed_snapshot_json jsonb, p_acknowledged boolean, p_external_number_checked boolean)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare c public.finance_tax_document_corrections%rowtype; snapshot jsonb; src jsonb; buyer jsonb; number text; typ text; doc_date date; seq integer; moment timestamptz:=now();
begin
 -- Serialize all cases for an original, including repeated Issue calls.
 perform 1 from public.finance_tax_invoices where id=(select original_tax_invoice_id from public.finance_tax_document_corrections where id=p_id) for update;
 select * into strict c from public.finance_tax_document_corrections where id=p_id for update;
 if public.tax_correction_authorized(c.original_combined_document_id is not null,'issue') is distinct from true then raise exception 'TAX_CORRECTION_PERMISSION_DENIED'; end if;
 if p_acknowledged is distinct from true or p_external_number_checked is distinct from true then raise exception 'TAX_CORRECTION_ISSUE_ACK_REQUIRED'; end if;
 if c.status='issued' then return c.id; end if;
 if c.status<>'approved' then raise exception 'TAX_CORRECTION_APPROVAL_REQUIRED'; end if;
 if c.draft_snapshot_json is distinct from p_reviewed_snapshot_json then raise exception 'TAX_CORRECTION_STALE_REVIEW'; end if;
 src:=public.tax_correction_source(c.original_tax_invoice_id,c.original_combined_document_id);
 if src is distinct from c.source_snapshot_json then raise exception 'TAX_CORRECTION_SOURCE_SUPERSEDED'; end if;
 if src #> '{tax,seller,logo_asset}' is null or src #> '{tax,seller,logo_asset}' is distinct from
   public.document_logo_evidence(src #>> '{tax,seller,logo_asset,path}') then raise exception 'TAX_CORRECTION_LOGO_EVIDENCE_INVALID'; end if;
 if c.correction_mode='cancel_and_reissue' then
   perform 1 from public.clients where id=(src #>> '{tax,customer,id}')::uuid for share;
   perform 1 from public.finance_customer_tax_profiles where client_id=(src #>> '{tax,customer,id}')::uuid for share;
   buyer:=public.get_finance_customer_tax_profile((src #>> '{tax,customer,id}')::uuid);
   if buyer->>'status' is distinct from 'verified' or buyer->'profile' is distinct from c.draft_snapshot_json #> '{tax,buyer_tax_profile,profile}'
   then raise exception 'TAX_CORRECTION_REVIEWED_BUYER_REQUIRED'; end if;
 end if;
 if c.issue_date>(moment at time zone 'Asia/Bangkok')::date then raise exception 'TAX_CORRECTION_DATES_INVALID'; end if;
 typ:=case when c.correction_mode='cancel_and_reissue' then case when c.original_combined_document_id is null then 'tax_invoice' else 'receipt_tax_invoice' end else c.correction_mode end;
 -- Documentary reissue retains the original face date (P.86/2542 clause 25).
 doc_date:=case when c.correction_mode in ('cancel_and_reissue','replacement_copy') then (src->>'document_date')::date else c.issue_date end;
 if typ='replacement_copy' then
   number:=src->>'document_no';
   select coalesce(max(copy_sequence),0)+1 into seq from public.finance_tax_correction_documents where document_no=number;
 else number:=public.tax_correction_number(typ,doc_date); end if;
 if typ<>'replacement_copy' and (exists(select 1 from public.finance_tax_invoices where tax_invoice_no=number)
   or exists(select 1 from public.finance_receipts where receipt_no=number)
   or exists(select 1 from public.finance_combined_documents where combined_no=number))
 then raise exception 'TAX_CORRECTION_NUMBER_COLLISION'; end if;
 snapshot:=c.draft_snapshot_json||jsonb_build_object('correction_id',c.id,'document_type',typ,'document_no',number,'document_date',doc_date,
   'original_document_no',src->>'document_no','original_document_date',src->>'document_date','issued_at',moment,'issued_by_user_id',auth.uid(),
   'issued_by_name',(select coalesce(nullif(full_name,''),email) from public.user_profiles where id=auth.uid()),
   'approval_evidence',c.approval_evidence,'copy_sequence',seq,'documentary_only',true,'payment_changed',false,'wht_changed',false);
 if c.correction_mode='cancel_and_reissue' then
   snapshot:=jsonb_set(snapshot,'{tax,document}',(snapshot #> '{tax,document}')||jsonb_build_object('tax_invoice_no',number,'issued_at',moment,'correction_id',c.id));
   if c.original_combined_document_id is not null then
     snapshot:=jsonb_set(snapshot,'{receipt,receipt}',(snapshot #> '{receipt,receipt}')||jsonb_build_object('receipt_no',number,'issued_at',moment,'correction_id',c.id));
   end if;
 end if;
 insert into public.finance_tax_correction_documents(id,document_type,document_no,document_date,issued_at,issued_by_user_id,copy_sequence,issued_snapshot_json)
 values(c.id,typ,number,doc_date,moment,auth.uid(),seq,snapshot);
 update public.finance_tax_document_corrections set status='issued',issued_at=moment,issued_by_user_id=auth.uid() where id=c.id;
 insert into public.finance_tax_correction_audit_events(correction_id,event_type,event_payload_json,actor_user_id)
 values(c.id,case when typ='replacement_copy' then 'copy_issued' else 'issued' end,
 jsonb_build_object('document_no',number,'original_document_no',src->>'document_no','documentary_only',true,'cash_created',false,'wht_changed',false,
   'external_number_checked',true,'lines',snapshot->'lines'),auth.uid());
 if c.correction_mode='cancel_and_reissue' then
   insert into public.finance_tax_correction_audit_events(correction_id,event_type,event_payload_json,actor_user_id)
   values(c.id,'replacement_linked',jsonb_build_object('original_tax_invoice_id',c.original_tax_invoice_id,'previous_correction_id',c.source_correction_id,
     'old_number',src->>'document_no','new_number',number,'original_state','replaced','original_row_unchanged',true),auth.uid());
 end if;
 return c.id;
end;
$function$

CREATE OR REPLACE FUNCTION public.payable_assert_distribution(p_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare s public.finance_payable_entitlement_sources%rowtype; d public.finance_vp_revenue_distributions%rowtype;
 actual jsonb; expected jsonb; evidence jsonb;
begin
 select * into s from public.finance_payable_entitlement_sources where distribution_id=p_id;
 if not found then raise exception 'PAYABLE_MATERIALIZATION_REQUIRED'; end if;
 select * into d from public.finance_vp_revenue_distributions where id=p_id;
 expected:=public.payable_frozen_components(s.frozen_distribution_json);
 if s.components_json is distinct from expected or s.frozen_distribution_json->>'id' is distinct from p_id::text
  or not exists(select 1 from public.finance_vp_revenue_distribution_audit a where a.distribution_id=p_id
   and a.event_type='finalized'
   and to_jsonb(jsonb_populate_record(null::public.finance_vp_revenue_distributions,a.evidence_json))=s.frozen_distribution_json)
  or (d.status='finalized' and s.frozen_distribution_json is distinct from to_jsonb(d))
  or d.status not in ('finalized','superseded')
  or s.status is distinct from (case d.status when 'finalized' then 'open' else 'superseded' end)
  or s.superseded_at is distinct from d.superseded_at
 then raise exception 'PAYABLE_FROZEN_EVIDENCE_INVALID'; end if;
 select coalesce(jsonb_agg(to_jsonb(e)-array['id','status','created_at','superseded_at']
  order by e.source_line_id::text,e.component_key),'[]') into actual from public.finance_payable_entitlements e where distribution_id=p_id;
 if actual is distinct from expected or exists(select 1 from public.finance_payable_entitlements e where distribution_id=p_id
  and (e.status<>s.status or e.superseded_at is distinct from s.superseded_at or e.created_at<>s.materialized_at))
 then raise exception 'PAYABLE_COMPONENT_INTEGRITY'; end if;
 evidence:=jsonb_build_object('distribution',s.frozen_distribution_json,'components',s.components_json);
 if not exists(select 1 from public.finance_payable_entitlement_audit a where distribution_id=p_id and event_type='materialized'
  and evidence_json=evidence and actor_id=s.materialized_by and created_at=s.materialized_at)
  or (s.status='superseded' and not exists(select 1 from public.finance_payable_entitlement_audit a
   where distribution_id=p_id and event_type='superseded' and evidence_json=evidence
    and actor_id=d.superseded_by and created_at=d.superseded_at))
  or (s.status='open' and exists(select 1 from public.finance_payable_entitlement_audit where distribution_id=p_id and event_type='superseded'))
 then raise exception 'PAYABLE_AUDIT_REQUIRED'; end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.prepare_finance_expense_payout(p_id uuid, p_expense uuid, p_version integer, p_paid_on date, p_bank uuid, p_cash uuid, p_actual_wht boolean, p_note text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare e public.finance_expenses%rowtype;p public.finance_payouts%rowtype;c jsonb;
begin
 if not public.expense_account_allowed(p_bank,p_cash,'record_outflow') then raise exception 'EXPENSE_ACCOUNT_DENIED'; end if;
 perform pg_advisory_xact_lock(hashtextextended('expense:'||p_expense,0));
 select * into strict e from public.finance_expenses where id=p_expense for update;
 if not public.expense_can_manage() and (e.created_by<>auth.uid() or e.origin<>'company_purchase'
  or exists(select 1 from public.finance_expense_obligations where expense_id=e.id) or p_actual_wht is distinct from false)
 then raise exception 'EXPENSE_FINANCE_PREPARATION_REQUIRED'; end if;
 if p_id is null or p_paid_on is null or p_paid_on<e.expense_date or p_paid_on>(now() at time zone 'Asia/Bangkok')::date
  or not public.treasury_location_active(p_bank,p_cash) then raise exception 'EXPENSE_PAYMENT_INVALID'; end if;
 select * into p from public.finance_payouts where id=p_id for update;
 if p.version is distinct from p_version or (p.id is not null and (p.source_model<>'expense_v1' or p.status<>'draft'
  or p.choices_json#>>'{0,expense_id}'<>p_expense::text)) then raise exception 'EXPENSE_STALE'; end if;
 c:=public.expense_payout_choice(p_expense,p_actual_wht);
 if (c#>>'{settlement,mode}'='company_bank' and p_bank is null) or (c#>>'{settlement,mode}'='company_cash' and p_cash is null)
 then raise exception 'EXPENSE_ACCOUNT_KIND_INVALID'; end if;
 if exists(select 1 from public.finance_payouts where source_model='expense_v1' and status='draft' and id<>p_id
  and choices_json#>>'{0,expense_id}'=p_expense::text) then raise exception 'EXPENSE_PAYMENT_DRAFT_EXISTS'; end if;
 if p.id is null then
  insert into public.finance_payouts(id,source_model,payee_id,paid_on,bank_account_id,cash_location_id,choices_json,gross_amount,wht_amount,net_amount,note,created_by,updated_by)
  values(p_id,'expense_v1',(c->>'payee_id')::uuid,p_paid_on,p_bank,p_cash,jsonb_build_array(c),(c->>'gross')::numeric,(c->>'wht')::numeric,
   (c->>'gross')::numeric-(c->>'wht')::numeric,coalesce(p_note,''),auth.uid(),auth.uid());
 else
  update public.finance_payouts set paid_on=p_paid_on,bank_account_id=p_bank,cash_location_id=p_cash,choices_json=jsonb_build_array(c),
   payee_id=(c->>'payee_id')::uuid,gross_amount=(c->>'gross')::numeric,wht_amount=(c->>'wht')::numeric,net_amount=(c->>'gross')::numeric-(c->>'wht')::numeric,
   note=coalesce(p_note,''),version=version+1,updated_at=clock_timestamp(),updated_by=auth.uid() where id=p_id;
 end if;
 insert into public.finance_payout_audit(payout_id,event_type,version,actor_id,evidence_json)
 select p_id,'saved',version,auth.uid(),to_jsonb(x) from public.finance_payouts x where id=p_id;
 return p_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.record_finance_paid_expense(p_id uuid, p_input jsonb, p_bank uuid, p_cash uuid, p_paid_on date, p_acknowledged boolean)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare e public.finance_expenses%rowtype;v integer;
begin
 if not public.expense_account_allowed(p_bank,p_cash,'record_outflow') or not public.expense_account_allowed(p_bank,p_cash,'confirm_outflow') then raise exception 'EXPENSE_ACCOUNT_DENIED'; end if;
 if p_acknowledged is distinct from true then raise exception 'EXPENSE_ACTUAL_PAYMENT_ACK_REQUIRED'; end if;
 perform pg_advisory_xact_lock(hashtextextended('expense:'||p_id,0));
 select * into e from public.finance_expenses where id=p_id;
 if e.id is not null then
  if exists(select 1 from public.finance_payouts where id=p_id and source_model='expense_v1' and status='confirmed'
   and bank_account_id is not distinct from p_bank and cash_location_id is not distinct from p_cash and paid_on=p_paid_on
   and gross_amount=(p_input->>'gross_amount')::numeric) and e.created_by=auth.uid()
   and exists(select 1 from public.finance_expense_audit a where a.expense_id=p_id and a.event_type='saved'
    and a.evidence_json->'immediate_request' = p_input) then return p_id; end if;
  raise exception 'EXPENSE_IDEMPOTENCY_CONFLICT';
 end if;
 perform public.save_finance_expense(p_id,null,p_input||jsonb_build_object('origin','company_purchase','bank_account_id',p_bank,'cash_location_id',p_cash,
  'personally_paid',false,'claimant_id',null,'reimbursement_requested',0,'vat_awareness','unknown','wht_awareness','unknown'));
 insert into public.finance_expense_audit(expense_id,event_type,actor_id,evidence_json)
 values(p_id,'saved',auth.uid(),jsonb_build_object('immediate_request',p_input));
 select version into v from public.finance_expenses where id=p_id;perform public.submit_finance_expense(p_id,v);
 insert into public.finance_expense_settlements(id,expense_id,mode,amount,reason,created_by)
 values(p_id,p_id,case when p_bank is not null then 'company_bank' else 'company_cash' end,(p_input->>'gross_amount')::numeric,'Actual company payment recorded; tax review pending',auth.uid());
 insert into public.finance_expense_audit(expense_id,event_type,actor_id,evidence_json)
 select p_id,'settlement_decided',auth.uid(),to_jsonb(s) from public.finance_expense_settlements s where id=p_id;
 perform public.prepare_finance_expense_payout(p_id,p_id,null,p_paid_on,p_bank,p_cash,false,p_input->>'note');
 perform public.confirm_finance_expense_payout(p_id,1,null,null,true);
 return p_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.replace_document_template_draft_structure(p_template_version_id uuid, p_sections_json jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_section jsonb; v_slot jsonb; v_section_id uuid; v_section_code text;
begin
  if not public.current_user_can_manage_finance_quotations() then raise exception 'Not allowed to save template structure'; end if;
  if not public.document_template_version_is_draft(p_template_version_id) then raise exception 'Only draft template versions can be edited'; end if;
  if p_sections_json is null or jsonb_typeof(p_sections_json) <> 'array' then raise exception 'Template sections must be an array'; end if;
  if exists (select 1 from public.finance_fee_agreements where selected_template_version_id = p_template_version_id) then raise exception 'Draft template structure is already referenced and cannot be replaced'; end if;
  delete from public.document_template_clause_slots where template_section_id in (select id from public.document_template_sections where template_version_id = p_template_version_id);
  delete from public.document_template_sections where template_version_id = p_template_version_id;
  for v_section in select value from jsonb_array_elements(p_sections_json) loop
    v_section_code := upper(btrim(coalesce(v_section->>'section_code', '')));
    if v_section_code = '' or btrim(coalesce(v_section->>'title', '')) = '' or coalesce((v_section->>'sort_order')::integer, 0) < 1 then raise exception 'Invalid template section'; end if;
    insert into public.document_template_sections(template_version_id, section_code, title, sort_order, is_required, allow_custom_after, risk_level, metadata_json, created_by_user_id, updated_by_user_id)
    values (p_template_version_id, v_section_code, btrim(v_section->>'title'), (v_section->>'sort_order')::integer, coalesce((v_section->>'is_required')::boolean, true), coalesce((v_section->>'allow_custom_after')::boolean, false), nullif(btrim(coalesce(v_section->>'risk_level', '')), ''), coalesce(v_section->'metadata_json', '{}'::jsonb), auth.uid(), auth.uid()) returning id into v_section_id;
    for v_slot in select value from jsonb_array_elements(coalesce(v_section->'slots', '[]'::jsonb)) loop
      if upper(btrim(coalesce(v_slot->>'slot_code', ''))) = '' or coalesce((v_slot->>'sort_order')::integer, 0) < 1 then raise exception 'Invalid template clause slot'; end if;
      insert into public.document_template_clause_slots(template_section_id, slot_code, clause_version_id, sort_order, is_required, allow_override, allow_suppress, allow_custom_after, risk_level, metadata_json, created_by_user_id, updated_by_user_id)
      values (v_section_id, upper(btrim(v_slot->>'slot_code')), nullif(v_slot->>'clause_version_id', '')::uuid, (v_slot->>'sort_order')::integer, coalesce((v_slot->>'is_required')::boolean, true), coalesce((v_slot->>'allow_override')::boolean, false), coalesce((v_slot->>'allow_suppress')::boolean, false), coalesce((v_slot->>'allow_custom_after')::boolean, false), nullif(btrim(coalesce(v_slot->>'risk_level', '')), ''), coalesce(v_slot->'metadata_json', '{}'::jsonb), auth.uid(), auth.uid());
    end loop;
  end loop;
  perform public.document_platform_audit('template_structure', p_template_version_id, 'replaced_draft_structure');
  return p_template_version_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.review_finance_expense_tax(p_id uuid, p_expense uuid, p_previous uuid, p_input jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare e public.finance_expenses%rowtype; old public.finance_expense_tax_reviews%rowtype;r public.finance_expense_tax_reviews%rowtype;
 vb numeric; vr numeric; wb numeric; wr numeric; calc jsonb; raw_input jsonb:=p_input; structured boolean:=p_input->>'schema_version'='2'; effective numeric;
begin
 if not public.expense_can_tax_review() then raise exception 'EXPENSE_TAX_PERMISSION_DENIED'; end if;
 if p_id is null or jsonb_typeof(p_input) is distinct from 'object' then raise exception 'EXPENSE_INPUT_INVALID'; end if;
 perform pg_advisory_xact_lock(hashtextextended('expense:'||p_expense,0));
 select * into e from public.finance_expenses where id=p_expense for update;
 if e.status is distinct from 'accepted' then raise exception 'EXPENSE_ACCEPTED_REQUIRED'; end if;
 if exists(select 1 from public.finance_expense_tax_reviews where id=p_id) then
  select * into r from public.finance_expense_tax_reviews where id=p_id;
  if r.expense_id<>p_expense or coalesce(r.request_json->'raw_input',r.request_json) is distinct from p_input then raise exception 'EXPENSE_IDEMPOTENCY_CONFLICT'; end if;
  return p_id;
 end if;
 select * into old from public.finance_expense_tax_reviews where expense_id=p_expense order by revision desc limit 1;
 if old.id is distinct from p_previous then raise exception 'EXPENSE_STALE'; end if;
 if structured then
  calc:=public.company_expense_tax_calculation(p_expense,p_input);
  if calc->>'ready'<>'true' then raise exception 'EXPENSE_TAX_DECISIONS_REQUIRED: %',calc->'missing';end if;
  effective:=(calc->>'gross')::numeric;
  p_input:=p_input||jsonb_build_object('raw_input',raw_input,'calculation',calc,
   'vat_state',case when p_input->>'vat_mode'='none' then 'none' else 'exists' end,
   'vat_base',calc->'vat_base','vat_rate',calc->'vat_rate','wht_base',calc->'wht_base','wht_rate',calc->'wht_rate',
   'eligibility',case when p_input->>'vat_mode'='none' then 'ineligible' else p_input->>'eligibility' end,'reason',coalesce(btrim(p_input->>'reason'),''));
  if p_input->>'eligibility'<>'eligible' then p_input:=p_input||jsonb_build_object('supplier_tax_id',null,'tax_document_reference',null,'tax_document_date',null,'company_name_status','unknown');end if;
 else
  if p_input ? 'calculation' or p_input ? 'raw_input' then raise exception 'EXPENSE_STRUCTURED_REVIEW_REQUIRED';end if;
  if old.request_json->>'schema_version'='2' then raise exception 'EXPENSE_STRUCTURED_REVIEW_REQUIRED';end if;
  effective:=e.gross_amount;
 end if;
 perform pg_advisory_xact_lock(500050);
 if p_input->>'eligibility'='eligible' and exists(select 1 from public.finance_expense_tax_reviews x
  where x.expense_id<>p_expense and x.eligibility='eligible' and x.supplier_tax_id=btrim(p_input->>'supplier_tax_id')
   and x.tax_document_reference=btrim(p_input->>'tax_document_reference') and x.tax_document_date=(p_input->>'tax_document_date')::date
   and not exists(select 1 from public.finance_expense_tax_reviews n where n.supersedes_id=x.id))
 then raise exception 'EXPENSE_INPUT_VAT_ALREADY_REVIEWED'; end if;
 -- Issued tax filings retain their sources. Do not silently recalculate any frozen filing.
 if exists(select 1 from public.finance_tax_filing_allocations a join public.finance_tax_position_facts f on f.id=a.tax_fact_id
  join public.finance_tax_source_revisions s on s.id=f.revision_id where s.source_type='expense' and s.source_id=p_expense)
 then raise exception 'EXPENSE_TAX_FILED_SOURCE_LOCKED'; end if;
 vb:=case when p_input->>'vat_state'='exists' then (p_input->>'vat_base')::numeric end;
 vr:=case when p_input->>'vat_state'='exists' then (p_input->>'vat_rate')::numeric end;
 wb:=case when p_input->>'wht_state'='withhold' then (p_input->>'wht_base')::numeric end;
 wr:=case when p_input->>'wht_state'='withhold' then (p_input->>'wht_rate')::numeric end;
 if vb is not null and (vb<>round(vb,2) or vb+case when structured then (calc->>'vat_amount')::numeric else round(vb*vr/100,2) end<>effective) then raise exception 'EXPENSE_VAT_TOTAL_INVALID'; end if;
 if wb is not null and (wb<>round(wb,2) or wb>effective or round(wb*wr/100,2)>=effective) then raise exception 'EXPENSE_WHT_INVALID'; end if;
 insert into public.finance_expense_tax_reviews(id,expense_id,revision,supersedes_id,vat_state,vat_base,vat_rate,vat_amount,eligibility,
  supplier_tax_id,tax_document_reference,tax_document_date,company_name_status,wht_state,wht_base,wht_rate,wht_amount,wht_exception,reason,request_json,reviewed_by)
 values(p_id,p_expense,coalesce(old.revision,0)+1,old.id,p_input->>'vat_state',vb,vr,case when structured and vb is not null then (calc->>'vat_amount')::numeric else round(vb*vr/100,2) end,p_input->>'eligibility',
  nullif(btrim(p_input->>'supplier_tax_id'),''),nullif(btrim(p_input->>'tax_document_reference'),''),nullif(p_input->>'tax_document_date','')::date,
  p_input->>'company_name_status',p_input->>'wht_state',wb,wr,round(wb*wr/100,2),p_input->>'wht_state'<>'none' and (e.personally_paid
   or exists(select 1 from public.finance_payouts where source_model='expense_v1' and status='confirmed' and wht_amount=0 and choices_json#>>'{0,expense_id}'=p_expense::text)),
  btrim(p_input->>'reason'),p_input,auth.uid()) returning * into r;
 perform public.tax_position_sync('expense',p_expense,r.reason);
 insert into public.finance_expense_audit(expense_id,event_type,actor_id,evidence_json) values(p_expense,'tax_reviewed',auth.uid(),to_jsonb(r));
 return p_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.review_finance_expense(p_id uuid, p_version integer, p_accept boolean, p_reason text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
 if not public.expense_can_manage() then raise exception 'EXPENSE_PERMISSION_DENIED';end if;
 perform pg_advisory_xact_lock(hashtextextended('expense:'||p_id,0));
 if public.company_purchase_request_declaration(p_id) is not null then raise exception 'EXPENSE_REQUEST_REVIEW_REQUIRED';end if;
 return public.review_finance_expense_before_purchase_flow(p_id,p_version,p_accept,p_reason);
end;
$function$

CREATE OR REPLACE FUNCTION public.save_document_template_alternative_group_draft(p_group_id uuid, p_template_version_id uuid, p_group_code text, p_title text, p_minimum_selection integer, p_maximum_selection integer, p_selection_required boolean, p_default_selected_slot_id uuid DEFAULT NULL::uuid, p_condition_rule_json jsonb DEFAULT NULL::jsonb, p_risk_level text DEFAULT NULL::text, p_sort_order integer DEFAULT 1, p_metadata_json jsonb DEFAULT '{}'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_id uuid; v_code text := upper(btrim(coalesce(p_group_code, ''))); v_risk text := nullif(lower(btrim(coalesce(p_risk_level, ''))), '');
begin
  if not public.current_user_can_manage_finance_quotations() then raise exception 'Not allowed to save an alternative group'; end if;
  if not public.document_template_version_is_draft(p_template_version_id) then raise exception 'Alternative groups can only be changed while the template version is draft'; end if;
  if v_code = '' or btrim(coalesce(p_title, '')) = '' or coalesce(p_minimum_selection, -1) < 0 or coalesce(p_maximum_selection, 0) < coalesce(p_minimum_selection, -1) or coalesce(p_maximum_selection, 0) < 1 or coalesce(p_sort_order, 0) < 1 or (v_risk is not null and v_risk not in ('low', 'medium', 'high', 'critical', 'informational')) then raise exception 'Invalid alternative group data'; end if;
  perform public.validate_document_condition_rule(p_condition_rule_json);
  if p_group_id is null then
    insert into public.document_template_alternative_groups(template_version_id, group_code, title, minimum_selection, maximum_selection, selection_required, default_selected_slot_id, condition_rule_json, risk_level, sort_order, metadata_json, created_by_user_id, updated_by_user_id)
    values (p_template_version_id, v_code, btrim(p_title), p_minimum_selection, p_maximum_selection, coalesce(p_selection_required, false), p_default_selected_slot_id, p_condition_rule_json, v_risk, p_sort_order, coalesce(p_metadata_json, '{}'::jsonb), auth.uid(), auth.uid()) returning id into v_id;
  else
    select id into v_id from public.document_template_alternative_groups where id = p_group_id and template_version_id = p_template_version_id for update;
    if v_id is null then raise exception 'Alternative group not found'; end if;
    update public.document_template_alternative_groups set group_code = v_code, title = btrim(p_title), minimum_selection = p_minimum_selection, maximum_selection = p_maximum_selection, selection_required = coalesce(p_selection_required, false), default_selected_slot_id = p_default_selected_slot_id, condition_rule_json = p_condition_rule_json, risk_level = v_risk, sort_order = p_sort_order, metadata_json = coalesce(p_metadata_json, '{}'::jsonb), updated_by_user_id = auth.uid(), updated_at = now() where id = v_id;
  end if;
  perform public.document_platform_audit('alternative_group', v_id, 'saved_draft');
  return v_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.save_document_template_clause_slot_draft(p_slot_id uuid, p_template_section_id uuid, p_slot_code text, p_clause_version_id uuid, p_sort_order integer, p_parent_slot_id uuid DEFAULT NULL::uuid, p_display_number text DEFAULT NULL::text, p_display_label text DEFAULT NULL::text, p_numbering_style text DEFAULT 'explicit'::text, p_numbering_depth integer DEFAULT 1, p_clause_type text DEFAULT 'mandatory'::text, p_alternative_group_id uuid DEFAULT NULL::uuid, p_condition_rule_json jsonb DEFAULT NULL::jsonb, p_is_required boolean DEFAULT true, p_allow_override boolean DEFAULT false, p_allow_suppress boolean DEFAULT false, p_allow_custom_after boolean DEFAULT false, p_risk_level text DEFAULT NULL::text, p_metadata_json jsonb DEFAULT '{}'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_id uuid; v_template_version_id uuid; v_code text := upper(btrim(coalesce(p_slot_code, '')));
begin
  select template_version_id into v_template_version_id from public.document_template_sections where id = p_template_section_id;
  if not public.current_user_can_manage_finance_quotations() or not public.document_template_version_is_draft(v_template_version_id) then raise exception 'Clause slots can only be changed while the template version is draft'; end if;
  if v_code = '' or coalesce(p_sort_order, 0) < 1 then raise exception 'Invalid template clause slot data'; end if;
  if p_slot_id is null then
    insert into public.document_template_clause_slots(template_section_id, slot_code, clause_version_id, sort_order, parent_slot_id, display_number, display_label, numbering_style, numbering_depth, clause_type, alternative_group_id, condition_rule_json, is_required, allow_override, allow_suppress, allow_custom_after, risk_level, metadata_json, created_by_user_id, updated_by_user_id)
    values (p_template_section_id, v_code, p_clause_version_id, p_sort_order, p_parent_slot_id, nullif(btrim(coalesce(p_display_number, '')), ''), nullif(btrim(coalesce(p_display_label, '')), ''), lower(btrim(coalesce(p_numbering_style, 'explicit'))), p_numbering_depth, lower(btrim(coalesce(p_clause_type, 'mandatory'))), p_alternative_group_id, p_condition_rule_json, coalesce(p_is_required, true), coalesce(p_allow_override, false), coalesce(p_allow_suppress, false), coalesce(p_allow_custom_after, false), nullif(lower(btrim(coalesce(p_risk_level, ''))), ''), coalesce(p_metadata_json, '{}'::jsonb), auth.uid(), auth.uid()) returning id into v_id;
  else
    select id into v_id from public.document_template_clause_slots where id = p_slot_id and template_section_id = p_template_section_id for update;
    if v_id is null then raise exception 'Template clause slot not found'; end if;
    update public.document_template_clause_slots set slot_code = v_code, clause_version_id = p_clause_version_id, sort_order = p_sort_order, parent_slot_id = p_parent_slot_id, display_number = nullif(btrim(coalesce(p_display_number, '')), ''), display_label = nullif(btrim(coalesce(p_display_label, '')), ''), numbering_style = lower(btrim(coalesce(p_numbering_style, 'explicit'))), numbering_depth = p_numbering_depth, clause_type = lower(btrim(coalesce(p_clause_type, 'mandatory'))), alternative_group_id = p_alternative_group_id, condition_rule_json = p_condition_rule_json, is_required = coalesce(p_is_required, true), allow_override = coalesce(p_allow_override, false), allow_suppress = coalesce(p_allow_suppress, false), allow_custom_after = coalesce(p_allow_custom_after, false), risk_level = nullif(lower(btrim(coalesce(p_risk_level, ''))), ''), metadata_json = coalesce(p_metadata_json, '{}'::jsonb), updated_by_user_id = auth.uid(), updated_at = now() where id = v_id;
  end if;
  perform public.document_platform_audit('template_slot', v_id, 'saved_draft');
  return v_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.save_document_template_family_draft(p_template_id uuid, p_document_type text, p_template_code text, p_name text, p_language_code text, p_metadata_json jsonb DEFAULT '{}'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_id uuid; v_status text; v_type text := lower(btrim(coalesce(p_document_type, ''))); v_code text := upper(btrim(coalesce(p_template_code, ''))); v_language text := lower(btrim(coalesce(p_language_code, 'th')));
begin
  if not public.current_user_can_manage_finance_quotations() then raise exception 'Not allowed to save document template'; end if;
  if v_type = '' or v_code = '' or btrim(coalesce(p_name, '')) = '' or v_language not in ('th', 'en') then raise exception 'Invalid document template draft data'; end if;
  if p_template_id is null then
    insert into public.document_templates(document_type, template_code, name, language_code, status, metadata_json, created_by_user_id, updated_by_user_id)
    values (v_type, v_code, btrim(p_name), v_language, 'draft', coalesce(p_metadata_json, '{}'::jsonb), auth.uid(), auth.uid()) returning id into v_id;
    perform public.document_platform_audit('template', v_id, 'created_draft');
  else
    select id, status into v_id, v_status from public.document_templates where id = p_template_id for update;
    if v_id is null then raise exception 'Document template not found'; end if;
    if v_status <> 'draft' then raise exception 'Only draft document template families can be edited'; end if;
    update public.document_templates set name = btrim(p_name), metadata_json = coalesce(p_metadata_json, '{}'::jsonb), updated_by_user_id = auth.uid(), updated_at = now() where id = v_id;
    perform public.document_platform_audit('template', v_id, 'updated_draft');
  end if;
  return v_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.save_document_template_section_draft(p_section_id uuid, p_template_version_id uuid, p_section_code text, p_title text, p_sort_order integer, p_parent_section_id uuid DEFAULT NULL::uuid, p_display_number text DEFAULT NULL::text, p_display_label text DEFAULT NULL::text, p_numbering_style text DEFAULT 'explicit'::text, p_numbering_depth integer DEFAULT 1, p_section_kind text DEFAULT 'normal'::text, p_condition_rule_json jsonb DEFAULT NULL::jsonb, p_is_required boolean DEFAULT true, p_allow_custom_after boolean DEFAULT false, p_risk_level text DEFAULT NULL::text, p_metadata_json jsonb DEFAULT '{}'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_id uuid; v_code text := upper(btrim(coalesce(p_section_code, '')));
begin
  if not public.current_user_can_manage_finance_quotations() or not public.document_template_version_is_draft(p_template_version_id) then raise exception 'Sections can only be changed while the template version is draft'; end if;
  if v_code = '' or btrim(coalesce(p_title, '')) = '' or coalesce(p_sort_order, 0) < 1 then raise exception 'Invalid template section data'; end if;
  if p_section_id is null then
    insert into public.document_template_sections(template_version_id, section_code, title, sort_order, parent_section_id, display_number, display_label, numbering_style, numbering_depth, section_kind, condition_rule_json, is_required, allow_custom_after, risk_level, metadata_json, created_by_user_id, updated_by_user_id)
    values (p_template_version_id, v_code, btrim(p_title), p_sort_order, p_parent_section_id, nullif(btrim(coalesce(p_display_number, '')), ''), nullif(btrim(coalesce(p_display_label, '')), ''), lower(btrim(coalesce(p_numbering_style, 'explicit'))), p_numbering_depth, lower(btrim(coalesce(p_section_kind, 'normal'))), p_condition_rule_json, coalesce(p_is_required, true), coalesce(p_allow_custom_after, false), nullif(lower(btrim(coalesce(p_risk_level, ''))), ''), coalesce(p_metadata_json, '{}'::jsonb), auth.uid(), auth.uid()) returning id into v_id;
  else
    select id into v_id from public.document_template_sections where id = p_section_id and template_version_id = p_template_version_id for update;
    if v_id is null then raise exception 'Template section not found'; end if;
    update public.document_template_sections set section_code = v_code, title = btrim(p_title), sort_order = p_sort_order, parent_section_id = p_parent_section_id, display_number = nullif(btrim(coalesce(p_display_number, '')), ''), display_label = nullif(btrim(coalesce(p_display_label, '')), ''), numbering_style = lower(btrim(coalesce(p_numbering_style, 'explicit'))), numbering_depth = p_numbering_depth, section_kind = lower(btrim(coalesce(p_section_kind, 'normal'))), condition_rule_json = p_condition_rule_json, is_required = coalesce(p_is_required, true), allow_custom_after = coalesce(p_allow_custom_after, false), risk_level = nullif(lower(btrim(coalesce(p_risk_level, ''))), ''), metadata_json = coalesce(p_metadata_json, '{}'::jsonb), updated_by_user_id = auth.uid(), updated_at = now() where id = v_id;
  end if;
  perform public.document_platform_audit('template_section', v_id, 'saved_draft');
  return v_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.save_document_template_variable_binding_draft(p_binding_id uuid, p_template_version_id uuid, p_variable_definition_id uuid, p_is_required boolean, p_formatting_override_json jsonb DEFAULT NULL::jsonb, p_fallback_override text DEFAULT NULL::text, p_metadata_json jsonb DEFAULT '{}'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_id uuid;
begin
  if not public.current_user_can_manage_finance_quotations() or not public.document_template_version_is_draft(p_template_version_id) then raise exception 'Template variable bindings can only be changed while draft'; end if;
  if not exists (select 1 from public.document_variable_definitions where id = p_variable_definition_id and status = 'active' and allowed_document_types ? 'fee_agreement') then raise exception 'Variable definition is not approved for fee agreements'; end if;
  if p_binding_id is null then
    insert into public.document_template_variable_bindings(template_version_id, variable_definition_id, is_required, formatting_override_json, fallback_override, metadata_json, created_by_user_id, updated_by_user_id)
    values (p_template_version_id, p_variable_definition_id, coalesce(p_is_required, false), p_formatting_override_json, p_fallback_override, coalesce(p_metadata_json, '{}'::jsonb), auth.uid(), auth.uid()) returning id into v_id;
  else
    select id into v_id from public.document_template_variable_bindings where id = p_binding_id and template_version_id = p_template_version_id for update;
    if v_id is null then raise exception 'Template variable binding not found'; end if;
    update public.document_template_variable_bindings set variable_definition_id = p_variable_definition_id, is_required = coalesce(p_is_required, false), formatting_override_json = p_formatting_override_json, fallback_override = p_fallback_override, metadata_json = coalesce(p_metadata_json, '{}'::jsonb), updated_by_user_id = auth.uid(), updated_at = now() where id = v_id;
  end if;
  perform public.document_platform_audit('template_variable_binding', v_id, 'saved_draft');
  return v_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.save_document_template_version_draft(p_template_version_id uuid, p_template_id uuid, p_language_code text, p_definition_json jsonb DEFAULT '{}'::jsonb, p_effective_from date DEFAULT NULL::date, p_effective_to date DEFAULT NULL::date)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_id uuid; v_version_no integer; v_previous_version_id uuid; v_language text := lower(btrim(coalesce(p_language_code, 'th')));
begin
  if not public.current_user_can_manage_finance_quotations() then raise exception 'Not allowed to save document template version'; end if;
  if v_language not in ('th', 'en') or p_definition_json is null or jsonb_typeof(p_definition_json) <> 'object' then raise exception 'Invalid document template version data'; end if;
  if p_effective_to is not null and p_effective_from is not null and p_effective_to < p_effective_from then raise exception 'Template effective date range is invalid'; end if;
  if p_template_version_id is null then
    if not exists (select 1 from public.document_templates where id = p_template_id and status <> 'retired') then raise exception 'Document template is unavailable'; end if;
    perform 1 from public.document_templates where id = p_template_id for update;
    select coalesce(max(version_no), 0) + 1 into v_version_no from public.document_template_versions where template_id = p_template_id and language_code = v_language;
    select id into v_previous_version_id from public.document_template_versions where template_id = p_template_id and language_code = v_language order by version_no desc limit 1;
    insert into public.document_template_versions(template_id, version_no, language_code, definition_json, status, effective_from, effective_to, previous_version_id, supersedes_version_id, created_by_user_id, updated_by_user_id)
    values (p_template_id, v_version_no, v_language, p_definition_json, 'draft', p_effective_from, p_effective_to, v_previous_version_id, v_previous_version_id, auth.uid(), auth.uid()) returning id into v_id;
    perform public.document_platform_audit('template_version', v_id, 'created_draft');
  else
    select id into v_id from public.document_template_versions where id = p_template_version_id for update;
    if v_id is null or not public.document_template_version_is_draft(v_id) then raise exception 'Only draft template versions can be edited'; end if;
    update public.document_template_versions set definition_json = p_definition_json, effective_from = p_effective_from, effective_to = p_effective_to, updated_by_user_id = auth.uid(), updated_at = now() where id = v_id;
    perform public.document_platform_audit('template_version', v_id, 'updated_draft');
  end if;
  return v_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.save_finance_direct_money_receipt(p_id uuid, p_expected_version integer, p_input jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare a public.finance_direct_money_receipts%rowtype; n public.finance_direct_money_receipts%rowtype; data jsonb; ts timestamptz:=clock_timestamp(); ev text;
begin
 if not public.money_allocation_admin() then raise exception 'DIRECT_MONEY_PERMISSION_DENIED'; end if;
 if p_id is null or p_expected_version is null or p_expected_version<0 then raise exception 'DIRECT_MONEY_STALE'; end if;
 perform pg_advisory_xact_lock(hashtextextended('direct_money:'||p_id::text,0));
 select * into a from public.finance_direct_money_receipts where id=p_id for update;
 if a.id is not null and a.status<>'draft' then raise exception 'DIRECT_MONEY_IMMUTABLE'; end if;
 data:=public.direct_money_payload(p_input);
 if a.id is not null and a.input_json=p_input and a.created_by=auth.uid() and p_expected_version in(a.version,a.version-1) then return a.id; end if;
 if coalesce(a.version,0)<>p_expected_version then raise exception 'DIRECT_MONEY_STALE'; end if;
 n:=jsonb_populate_record(null::public.finance_direct_money_receipts,data);
 if a.id is null then
  n.id:=p_id; n.status:='draft'; n.version:=1; n.created_by:=auth.uid(); n.created_at:=ts; n.updated_at:=ts; n.input_json:=p_input;
  insert into public.finance_direct_money_receipts select n.* returning * into a; ev:='created';
 else
  update public.finance_direct_money_receipts set client_id=n.client_id,payer_name=n.payer_name,case_id=n.case_id,advisory_matter_id=n.advisory_matter_id,
   received_on=n.received_on,method=n.method,receiving_bank_account_id=n.receiving_bank_account_id,cash_location=n.cash_location,currency=n.currency,
   cash_amount=n.cash_amount,wht_amount=n.wht_amount,amount_before_vat=n.amount_before_vat,vat_amount=n.vat_amount,gross_amount=n.gross_amount,
   reference_no=n.reference_no,evidence_reference=n.evidence_reference,note=n.note,lines_json=n.lines_json,unclassified=n.unclassified,input_json=p_input,
   version=version+1,updated_at=ts where id=p_id returning * into a; ev:='saved';
 end if;
 insert into public.finance_direct_money_receipt_audit(receipt_id,event_type,version,actor_id,created_at,evidence_json)
 values(a.id,ev,a.version,auth.uid(),ts,to_jsonb(a)); return a.id;
end;
$function$

CREATE OR REPLACE FUNCTION public.save_finance_payout_before_expense(p_id uuid, p_payee_id uuid, p_paid_on date, p_bank_account_id uuid, p_cash_location_id uuid, p_choices jsonb, p_note text, p_expected_version integer)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare old public.finance_payouts%rowtype; choices jsonb; gross numeric; wht numeric;
begin
 if not public.payout_can_manage() then raise exception 'PAYOUT_PERMISSION_DENIED'; end if;
 perform pg_advisory_xact_lock(hashtextextended('payout_lifecycle',0));
 select * into old from public.finance_payouts where id=p_id for update;
 if old.id is not null and old.status<>'draft' then raise exception 'PAYOUT_HISTORY_IMMUTABLE'; end if;
 if old.version is distinct from p_expected_version then raise exception 'PAYOUT_STALE'; end if;
 if p_id is null or p_paid_on is null or p_paid_on>(now() at time zone 'Asia/Bangkok')::date
  or not exists(select 1 from public.finance_payees where id=p_payee_id and is_active)
  or not public.treasury_location_active(p_bank_account_id,p_cash_location_id)
  or not public.treasury_can_view(p_bank_account_id,p_cash_location_id) then raise exception 'PAYOUT_INPUT_INVALID'; end if;
 choices:=public.payout_choices(p_payee_id,p_choices);
 select sum((x->>'gross')::numeric),sum((x->>'wht')::numeric) into gross,wht from jsonb_array_elements(choices) x;
 if gross-wht<=0 then raise exception 'PAYOUT_NET_REQUIRED'; end if;
 if old.id is null then
  insert into public.finance_payouts(id,payee_id,paid_on,bank_account_id,cash_location_id,choices_json,gross_amount,wht_amount,net_amount,note,created_by,updated_by)
   values(p_id,p_payee_id,p_paid_on,p_bank_account_id,p_cash_location_id,choices,gross,wht,gross-wht,coalesce(p_note,''),auth.uid(),auth.uid());
 else
  update public.finance_payouts set payee_id=p_payee_id,paid_on=p_paid_on,bank_account_id=p_bank_account_id,cash_location_id=p_cash_location_id,
   choices_json=choices,gross_amount=gross,wht_amount=wht,net_amount=gross-wht,note=coalesce(p_note,''),version=version+1,updated_at=clock_timestamp(),updated_by=auth.uid() where id=p_id;
 end if;
 insert into public.finance_payout_audit(payout_id,event_type,version,actor_id,evidence_json)
  select id,'saved',version,auth.uid(),to_jsonb(p) from public.finance_payouts p where id=p_id;
 return p_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.save_finance_vp_received_distribution(p_payment_id uuid, p_direct_id uuid, p_expected_id uuid, p_expected_version integer, p_source jsonb, p_choices jsonb, p_note text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare a public.finance_vp_revenue_distributions%rowtype; prev public.finance_vp_revenue_distributions%rowtype;
 s jsonb; c jsonb; ev text; ts timestamptz;
begin
 if not public.money_allocation_admin() then raise exception 'VP_DISTRIBUTION_PERMISSION_DENIED'; end if;
 if (p_expected_id is null)<>(p_expected_version is null) or (p_expected_version is not null and p_expected_version<1)
 then raise exception 'VP_DISTRIBUTION_STALE'; end if;
 perform public.vp_received_lock(p_payment_id,p_direct_id); s:=public.vp_received_source(p_payment_id,p_direct_id);
 if s is distinct from p_source then raise exception 'VP_DISTRIBUTION_SOURCE_CHANGED'; end if;
 if s->'blockers' is distinct from '[]'::jsonb or jsonb_array_length(s->'lines')=0 then raise exception 'VP_DISTRIBUTION_SOURCE_UNPROVEN'; end if;
 if p_note is null or length(p_note)>2000 then raise exception 'VP_DISTRIBUTION_CHOICES_INVALID'; end if;
 c:=public.vp_distribution_choices(s,p_choices,false);
 select * into a from public.finance_vp_revenue_distributions where payment_id is not distinct from p_payment_id and direct_money_receipt_id is not distinct from p_direct_id and status<>'superseded' for update;
 if a.id is null then
  select * into prev from public.finance_vp_revenue_distributions where payment_id is not distinct from p_payment_id and direct_money_receipt_id is not distinct from p_direct_id order by revision desc limit 1;
 elsif a.previous_id is not null then
  select * into prev from public.finance_vp_revenue_distributions where id=a.previous_id;
 end if;
 -- Only an identical current operation or its immediate retry is idempotent.
 if a.id is not null and a.status='draft' and a.source_snapshot_json=s and a.decisions_json=c and a.note=btrim(p_note)
   and ((p_expected_id=a.id and p_expected_version in (a.version,a.version-1))
     or (a.version=1 and a.created_by=auth.uid() and (
       (a.revision=1 and a.previous_id is null and p_expected_id is null and p_expected_version is null)
       or (a.previous_id=p_expected_id and prev.id=a.previous_id and prev.version=p_expected_version and prev.status='superseded')))) then return a.id; end if;
 if (a.id is not null and (a.id is distinct from p_expected_id or a.version is distinct from p_expected_version))
   or (a.id is null and (prev.id is distinct from p_expected_id or (prev.id is not null and prev.version is distinct from p_expected_version)))
 then raise exception 'VP_DISTRIBUTION_STALE'; end if;
 ts:=clock_timestamp();
 if a.id is null then
  insert into public.finance_vp_revenue_distributions(payment_id,direct_money_receipt_id,money_allocation_id,revision,previous_id,source_snapshot_json,decisions_json,note,created_at,created_by,updated_at)
  values(p_payment_id,p_direct_id,(s#>>'{money_allocation,id}')::uuid,coalesce(prev.revision,0)+1,prev.id,s,c,btrim(p_note),ts,auth.uid(),ts)
  returning * into a; ev:='created';
 else
  if a.status<>'draft' then raise exception 'VP_DISTRIBUTION_HISTORY_IMMUTABLE'; end if;
  update public.finance_vp_revenue_distributions set money_allocation_id=(s#>>'{money_allocation,id}')::uuid,
   source_snapshot_json=s,decisions_json=c,note=btrim(p_note),version=version+1,updated_at=ts where id=a.id returning * into a; ev:='saved';
 end if;
 insert into public.finance_vp_revenue_distribution_audit(distribution_id,event_type,actor_id,created_at,evidence_json)
 values(a.id,ev,auth.uid(),ts,to_jsonb(a));
 return a.id;
end;
$function$

CREATE OR REPLACE FUNCTION public.set_document_template_version_status(p_template_version_id uuid, p_next_status text, p_approval_note text DEFAULT NULL::text, p_approval_reference text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_version public.document_template_versions%rowtype; v_template public.document_templates%rowtype; v_next text := lower(btrim(coalesce(p_next_status, ''))); v_hash text; v_structure_hash text; v_normalized_text_hash text;
begin
  if not public.current_user_can_manage_finance_quotations() then raise exception 'Not allowed to update template version status'; end if;
  select * into v_version from public.document_template_versions where id = p_template_version_id for update;
  if v_version.id is null then raise exception 'Template version not found'; end if;
  select * into v_template from public.document_templates where id = v_version.template_id for update;
  if not ((v_version.status = 'draft' and v_next = 'under_review') or (v_version.status = 'under_review' and v_next in ('draft', 'published')) or (v_version.status = 'published' and v_next = 'retired')) then raise exception 'Invalid template version status transition'; end if;
  if v_next in ('published', 'retired') and not public.current_user_is_document_platform_partner() then raise exception 'Only an Admin or Partner can publish or retire template versions'; end if;
  if v_next = 'published' then
    if coalesce(v_template.metadata_json->>'inactive_shell', 'false') = 'true'
       or coalesce(v_version.definition_json->>'inactive_shell', 'false') = 'true' then
      raise exception 'Inactive template shells cannot be published';
    end if;
    if coalesce(v_template.metadata_json->>'legal_wording_approved', 'false') <> 'true'
       or coalesce(v_version.definition_json->>'legal_wording_approved', 'false') <> 'true' then
      raise exception 'Approved legal wording is required before publication';
    end if;
    perform public.validate_document_condition_rule(v_version.condition_rule_json);
    perform public.validate_document_signature_requirements(v_version.signature_requirements_json);
    if v_version.definition_json ? 'clause_version_ids' and exists (select 1 from public.document_template_sections where template_version_id = v_version.id) then raise exception 'New normalized template versions must not also define clause_version_ids in definition_json'; end if;
    if not exists (select 1 from public.document_template_sections where template_version_id = v_version.id) or exists (select 1 from public.document_template_clause_slots s join public.document_template_sections sec on sec.id = s.template_section_id left join public.document_clause_versions cv on cv.id = s.clause_version_id where sec.template_version_id = v_version.id and (s.clause_version_id is null or cv.status <> 'published' or cv.language_code <> v_version.language_code)) then raise exception 'Template version structure requires published, language-matched clause versions'; end if;
    if exists (select 1 from public.document_template_alternative_groups g left join public.document_template_clause_slots s on s.id = g.default_selected_slot_id where g.template_version_id = v_version.id and (g.default_selected_slot_id is not null and (s.id is null or s.alternative_group_id <> g.id))) then raise exception 'Alternative group default selections must be slots in their own group'; end if;
    if exists (select 1 from public.document_template_variable_bindings b join public.document_variable_definitions v on v.id = b.variable_definition_id where b.template_version_id = v_version.id and (v.status <> 'active' or not (v.allowed_document_types ? 'fee_agreement'))) then raise exception 'Template variable bindings must use active variables approved for fee agreements'; end if;
    v_hash := public.compute_document_template_version_content_hash(v_version.id);
    v_structure_hash := public.compute_document_template_version_structure_hash(v_version.id);
    v_normalized_text_hash := public.compute_document_template_version_normalized_text_hash(v_version.id);
    update public.document_templates set status = 'active', updated_by_user_id = auth.uid(), updated_at = now() where id = v_version.template_id and status <> 'retired';
  end if;
  update public.document_template_versions set status = v_next, reviewed_by_user_id = case when v_next = 'published' then auth.uid() else reviewed_by_user_id end, reviewed_at = case when v_next = 'published' then now() else reviewed_at end, published_by_user_id = case when v_next = 'published' then auth.uid() else published_by_user_id end, published_at = case when v_next = 'published' then now() else published_at end, retired_by_user_id = case when v_next = 'retired' then auth.uid() else retired_by_user_id end, retired_at = case when v_next = 'retired' then now() else retired_at end, approval_note = case when v_next in ('published', 'retired') then nullif(btrim(coalesce(p_approval_note, '')), '') else approval_note end, approval_reference = case when v_next in ('published', 'retired') then nullif(btrim(coalesce(p_approval_reference, '')), '') else approval_reference end, content_hash = case when v_next = 'published' then v_hash else content_hash end, structure_hash = case when v_next = 'published' then v_structure_hash else structure_hash end, normalized_text_hash = case when v_next = 'published' then v_normalized_text_hash else normalized_text_hash end, updated_by_user_id = auth.uid(), updated_at = now() where id = v_version.id;
  perform public.document_platform_audit('template_version', v_version.id, v_next, jsonb_build_object('approval_note', nullif(btrim(coalesce(p_approval_note, '')), ''), 'approval_reference', nullif(btrim(coalesce(p_approval_reference, '')), '')));
  return v_version.id;
end;
$function$

CREATE OR REPLACE FUNCTION public.set_finance_authorized_signer_active(p_signer_id uuid, p_is_active boolean)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_signer public.finance_authorized_signers%rowtype;
begin
  if not public.current_user_can_manage_finance_quotations() then
    raise exception 'Not allowed to update authorized signer';
  end if;

  select * into v_signer
  from public.finance_authorized_signers
  where id = p_signer_id
  for update;

  if v_signer.id is null then
    raise exception 'Authorized signer not found';
  end if;

  if not p_is_active and v_signer.is_default then
    raise exception 'กรุณาตั้งผู้ลงนามเริ่มต้นคนใหม่ก่อนปิดใช้งานรายนี้';
  end if;

  update public.finance_authorized_signers
  set
    is_active = p_is_active,
    updated_at = now(),
    updated_by_user_id = auth.uid()
  where id = v_signer.id;

  return v_signer.id;
end;
$function$

CREATE OR REPLACE FUNCTION public.set_finance_billing_plan_status(p_billing_plan_id uuid, p_next_status text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_plan public.finance_billing_plans%rowtype;
  v_agreement public.finance_fee_agreements%rowtype;
  v_next_status text := lower(btrim(coalesce(p_next_status, '')));
  v_installment_count integer;
  v_amount_before_tax numeric(14, 2);
  v_vat_amount numeric(14, 2);
  v_total_amount numeric(14, 2);
  v_non_cancelled_installment_count integer;
begin
  if not public.current_user_can_manage_finance_quotations() then
    raise exception 'Not allowed to update finance billing plan status';
  end if;

  select *
    into v_plan
  from public.finance_billing_plans
  where id = p_billing_plan_id
  for update;

  if v_plan.id is null then
    raise exception 'Billing plan not found';
  end if;

  if not (
    (v_plan.status = 'draft' and v_next_status in ('active', 'cancelled'))
    or (v_plan.status = 'active' and v_next_status in ('completed', 'cancelled'))
  ) then
    raise exception 'Invalid finance billing plan status transition';
  end if;

  if v_plan.status = 'draft' and v_next_status = 'active' then
    select *
      into v_agreement
    from public.finance_fee_agreements
    where id = v_plan.fee_agreement_id
    for update;

    if v_agreement.id is null then
      raise exception 'Fee agreement not found';
    end if;

    if not public.finance_fee_agreement_is_billing_eligible(v_agreement.id) then
      raise exception 'Billing plan requires an eligible commercial engagement';
    end if;

    if v_plan.billing_method <> v_agreement.billing_method then
      raise exception 'Billing plan method must match the fee agreement';
    end if;

    select count(*)::integer
      into v_installment_count
    from public.finance_billing_installments
    where billing_plan_id = v_plan.id
      and status <> 'cancelled';

    if v_installment_count = 0 then
      raise exception 'Billing plan requires at least one non-cancelled installment before activation';
    end if;

    if v_plan.installment_count <> v_installment_count then
      raise exception 'Billing plan installment count must match non-cancelled installments';
    end if;

    if (v_plan.billing_method = 'single' and v_installment_count <> 1)
      or (v_plan.billing_method = 'installments' and v_installment_count < 2) then
      raise exception 'Billing plan installment count is incompatible with its billing method';
    end if;

    if v_plan.amount_before_tax <> v_agreement.amount_before_tax
      or v_plan.vat_amount <> v_agreement.vat_amount
      or v_plan.total_amount <> v_agreement.total_amount then
      raise exception 'Billing plan totals must match the fee agreement before activation';
    end if;

    if exists (
      select 1
      from public.finance_billing_installments installment
      left join public.finance_billing_installment_items installment_item
        on installment_item.billing_installment_id = installment.id
      where installment.billing_plan_id = v_plan.id
      group by installment.id, installment.amount_before_tax, installment.vat_amount, installment.total_amount
      having count(installment_item.id) = 0
        or coalesce(sum(installment_item.amount_before_tax), 0) <> installment.amount_before_tax
        or coalesce(sum(installment_item.vat_amount), 0) <> installment.vat_amount
        or coalesce(sum(installment_item.total_amount), 0) <> installment.total_amount
    ) then
      raise exception 'Every billing installment must have matching installment items before activation';
    end if;

    select
      coalesce(sum(amount_before_tax), 0),
      coalesce(sum(vat_amount), 0),
      coalesce(sum(total_amount), 0)
    into
      v_amount_before_tax,
      v_vat_amount,
      v_total_amount
    from public.finance_billing_installments
    where billing_plan_id = v_plan.id
      and status <> 'cancelled';

    if v_amount_before_tax <> v_plan.amount_before_tax
      or v_vat_amount <> v_plan.vat_amount
      or v_total_amount <> v_plan.total_amount then
      raise exception 'Billing installment totals must match the billing plan before activation';
    end if;

    if exists (
      select 1
      from public.finance_billing_installment_items installment_item
      join public.finance_billing_installments installment
        on installment.id = installment_item.billing_installment_id
      join public.finance_fee_agreement_items agreement_item
        on agreement_item.id = installment_item.fee_agreement_item_id
      where installment.billing_plan_id = v_plan.id
        and agreement_item.fee_agreement_id <> v_agreement.id
    ) then
      raise exception 'Billing plan contains an item from another fee agreement';
    end if;

    if exists (
      select 1
      from public.finance_fee_agreement_items agreement_item
      left join public.finance_billing_installment_items installment_item
        on installment_item.fee_agreement_item_id = agreement_item.id
      left join public.finance_billing_installments installment
        on installment.id = installment_item.billing_installment_id
        and installment.billing_plan_id = v_plan.id
        and installment.status <> 'cancelled'
      where agreement_item.fee_agreement_id = v_agreement.id
      group by agreement_item.id, agreement_item.amount_before_tax, agreement_item.vat_amount, agreement_item.line_total
      having coalesce(sum(installment_item.amount_before_tax) filter (where installment.id is not null), 0)
          <> agreement_item.amount_before_tax
        or coalesce(sum(installment_item.vat_amount) filter (where installment.id is not null), 0)
          <> agreement_item.vat_amount
        or coalesce(sum(installment_item.total_amount) filter (where installment.id is not null), 0)
          <> agreement_item.line_total
    ) then
      raise exception 'Billing plan allocations must exactly match every fee agreement item before activation';
    end if;

    if exists (
      with allocation_input as (
        select
          agreement_item.id as fee_agreement_item_id,
          agreement_item.vat_applicable,
          agreement_item.vat_rate,
          agreement_item.vat_amount as source_vat_amount,
          installment_item.amount_before_tax,
          installment_item.vat_amount as allocated_vat_amount,
          installment_item.total_amount as allocated_total_amount,
          row_number() over (
            partition by agreement_item.id
            order by installment.installment_no, installment.sort_order, installment_item.sort_order, installment_item.id
          ) as allocation_row_no,
          count(*) over (partition by agreement_item.id) as allocation_count
        from public.finance_billing_installment_items installment_item
        join public.finance_billing_installments installment
          on installment.id = installment_item.billing_installment_id
        join public.finance_fee_agreement_items agreement_item
          on agreement_item.id = installment_item.fee_agreement_item_id
        where installment.billing_plan_id = v_plan.id
          and installment.status <> 'cancelled'
      ), rounded as (
        select
          allocation_input.*,
          case when vat_applicable then round(amount_before_tax * vat_rate / 100, 2) else 0 end as rounded_vat_amount
        from allocation_input
      ), derived as (
        select
          rounded.*,
          case
            when not vat_applicable then 0
            when allocation_row_no = allocation_count then source_vat_amount
              - coalesce(sum(rounded_vat_amount) over (
                partition by fee_agreement_item_id
                order by allocation_row_no
                rows between unbounded preceding and 1 preceding
              ), 0)
            else rounded_vat_amount
          end as expected_vat_amount
        from rounded
      )
      select 1
      from derived
      where allocated_vat_amount <> expected_vat_amount
        or allocated_total_amount <> amount_before_tax + expected_vat_amount
        or expected_vat_amount < 0
    ) then
      raise exception 'Billing plan VAT allocations must preserve the source fee agreement item tax treatment';
    end if;
  end if;

  -- Phase 4 Invoice issuance will set installments to invoiced through a controlled invoice RPC.
  if v_plan.status = 'active' and v_next_status = 'completed' then
    select count(*)::integer
      into v_non_cancelled_installment_count
    from public.finance_billing_installments
    where billing_plan_id = v_plan.id
      and status <> 'cancelled';

    if v_non_cancelled_installment_count = 0 then
      raise exception 'Billing plan requires at least one non-cancelled invoiced installment before completion';
    end if;

    if exists (
      select 1
      from public.finance_billing_installments
      where billing_plan_id = v_plan.id
        and status <> 'cancelled'
        and status <> 'invoiced'
    ) then
      raise exception 'Billing plan cannot be completed until every non-cancelled installment is invoiced';
    end if;
  end if;

  if v_next_status = 'cancelled' then
    if v_plan.status = 'draft' then
      if exists (
        select 1
        from public.finance_billing_installments
        where billing_plan_id = v_plan.id
          and status <> 'pending'
      ) then
        raise exception 'Draft billing plan contains an unexpected installment status';
      end if;

      update public.finance_billing_installments
      set
        status = 'cancelled',
        cancelled_at = now(),
        updated_by_user_id = auth.uid(),
        updated_at = now()
      where billing_plan_id = v_plan.id
        and status = 'pending';
    else
      if exists (
        select 1
        from public.finance_billing_installments
        where billing_plan_id = v_plan.id
          and status = 'invoiced'
      ) then
        raise exception 'Billing plan with invoiced installments cannot be cancelled in this phase';
      end if;

      update public.finance_billing_installments
      set
        status = 'cancelled',
        ready_to_invoice_at = null,
        cancelled_at = now(),
        updated_by_user_id = auth.uid(),
        updated_at = now()
      where billing_plan_id = v_plan.id
        and status in ('pending', 'ready_to_invoice');
    end if;
  end if;

  update public.finance_billing_plans
  set
    status = v_next_status,
    updated_by_user_id = auth.uid(),
    updated_at = now()
  where id = v_plan.id;

  return v_plan.id;
end;
$function$

CREATE OR REPLACE FUNCTION public.set_finance_fee_agreement_status(p_fee_agreement_id uuid, p_next_status text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_agreement public.finance_fee_agreements%rowtype;
  v_next text := lower(btrim(coalesce(p_next_status, '')));
  v_event text;
  v_retired boolean;
begin
  if not public.current_user_can_manage_finance_quotations() then
    raise exception 'Not allowed to update finance fee agreement status';
  end if;
  select * into v_agreement
  from public.finance_fee_agreements
  where id = p_fee_agreement_id
  for update;
  if v_agreement.id is null then raise exception 'Fee agreement not found'; end if;
  if v_agreement.engagement_basis = 'accepted_quotation' then
    raise exception 'Accepted quotation engagements do not use formal document lifecycle actions';
  end if;
  if v_agreement.status = 'sent' and v_next = 'signed' then
    raise exception 'กรุณาบันทึกหลักฐานการลงนามก่อนเปลี่ยนสถานะเป็นลงนามแล้ว';
  end if;
  if not (
    (v_agreement.status = 'draft' and v_next in ('under_review', 'cancelled'))
    or (v_agreement.status = 'under_review' and v_next in ('sent', 'cancelled'))
    or (v_agreement.status = 'signed' and v_next = 'completed')
    or (v_agreement.status = 'draft' and v_next = 'active')
    or (v_agreement.status = 'active' and v_next in ('completed', 'cancelled'))
  ) then
    raise exception 'Invalid finance fee agreement status transition';
  end if;
  if v_next in ('under_review', 'sent', 'active')
    and (v_agreement.source_document_snapshot_json is null or v_agreement.commercial_terms_snapshot_json is null)
  then
    raise exception 'Fee agreement source evidence is required';
  end if;
  if v_next = 'sent' and v_agreement.agreement_date is null then
    raise exception 'กรุณาระบุวันที่ทำสัญญาก่อนส่งเอกสาร';
  end if;
  if v_next = 'sent'
    and (v_agreement.agreement_no is null or v_agreement.legal_terms_json is null or v_agreement.signatories_json is null)
  then
    raise exception 'Fee agreement legal document data is not ready';
  end if;
  if v_next = 'sent' and v_agreement.selected_template_version_id is not null then
    perform public.validate_finance_fee_agreement_template_ready(v_agreement.id);
    select tv.status = 'retired' or t.status = 'retired'
    into v_retired
    from public.document_template_versions as tv
    join public.document_templates as t on t.id = tv.template_id
    where tv.id = v_agreement.selected_template_version_id;
    if coalesce(v_retired, false)
      and (
        v_agreement.retired_template_use_approved_version_id is distinct from v_agreement.selected_template_version_id
        or v_agreement.retired_template_use_approved_by_user_id is null
        or nullif(btrim(coalesce(v_agreement.retired_template_use_reason, '')), '') is null
      )
    then
      raise exception 'Partner approval is required before sending an agreement that uses a retired template version';
    end if;
  end if;
  if v_next = 'cancelled'
    and exists (
      select 1 from public.finance_billing_plans
      where fee_agreement_id = v_agreement.id
        and status <> 'cancelled'
    )
  then
    raise exception 'Cancel the Billing Plan before cancelling this agreement';
  end if;

  update public.finance_fee_agreements
  set status = v_next,
      sent_at = case when v_next = 'sent' then now() else sent_at end,
      sent_by_user_id = case when v_next = 'sent' then auth.uid() else sent_by_user_id end,
      cancelled_at = case when v_next = 'cancelled' then now() else cancelled_at end,
      cancelled_by_user_id = case when v_next = 'cancelled' then auth.uid() else cancelled_by_user_id end,
      updated_by_user_id = auth.uid(),
      updated_at = now()
  where id = v_agreement.id;

  v_event := v_next;
  perform public.record_finance_fee_agreement_version(
    v_agreement.id,
    v_event,
    null,
    jsonb_build_object('from_status', v_agreement.status, 'to_status', v_next)
  );
  return v_agreement.id;
end;
$function$

CREATE OR REPLACE FUNCTION public.set_finance_quotation_service_pattern_active(p_pattern_id uuid, p_is_active boolean)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_pattern_id uuid;
  v_actor_email text;
  v_actor_name text;
begin
  if not public.current_user_can_manage_finance_quotations() then
    raise exception 'Not allowed to manage quotation service patterns';
  end if;

  select pattern.id
  into v_pattern_id
  from public.finance_quotation_service_patterns pattern
  where pattern.id = p_pattern_id
  for update;

  if v_pattern_id is null then
    raise exception 'Quotation service pattern not found';
  end if;

  select
    auth_user.email,
    coalesce(nullif(btrim(profile.staff_name), ''), nullif(btrim(profile.full_name), ''), auth_user.email, auth.uid()::text)
  into v_actor_email, v_actor_name
  from auth.users auth_user
  left join public.user_profiles profile on profile.id = auth_user.id
  where auth_user.id = auth.uid();

  update public.finance_quotation_service_patterns pattern
  set
    is_active = coalesce(p_is_active, false),
    updated_at = now(),
    updated_by_user_id = auth.uid(),
    updated_by_email = v_actor_email,
    updated_by_name = v_actor_name
  where pattern.id = v_pattern_id;

  return v_pattern_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.set_finance_quotation_status_v2(p_quotation_id uuid, p_next_status text, p_cancel_reason text, p_user_id uuid, p_user_email text, p_user_name text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  q public.finance_quotations%rowtype;
  v_next_status text := lower(btrim(coalesce(p_next_status, '')));
  v_item_before numeric(14,2);
  v_item_vat numeric(14,2);
  v_item_total numeric(14,2);
  v_payment public.finance_quotation_payment_terms%rowtype;
  v_client jsonb;
  v_matter jsonb;
  v_company jsonb := '{}'::jsonb;
  v_signer jsonb := '{}'::jsonb;
  v_items jsonb;
  v_installments jsonb;
  v_snapshot jsonb;
  v_actor_name text;
begin
  if not public.current_user_can_manage_finance_quotations() then raise exception 'Not allowed to update finance quotation status'; end if;
  select * into q from public.finance_quotations where id = p_quotation_id for update;
  if q.id is null then raise exception 'Quotation not found'; end if;

  if not (q.status = 'draft' and v_next_status = 'sent' and q.client_id is null) then
    return public.set_finance_quotation_status(p_quotation_id, p_next_status, p_cancel_reason, p_user_id, p_user_email, p_user_name);
  end if;
  if q.customer_source_type <> 'prospect' or nullif(btrim(coalesce(q.prospect_name, '')), '') is null then
    raise exception 'Prospect identity is incomplete';
  end if;
  if q.valid_until is not null and q.valid_until < q.issue_date then raise exception 'Valid until cannot be before issue date'; end if;
  if q.case_id is not null and q.advisory_matter_id is not null then raise exception 'Select either case or advisory matter, not both'; end if;

  v_client := coalesce(q.client_snapshot_json, '{}'::jsonb) || jsonb_build_object(
    'source_type', 'prospect', 'id', null, 'name', q.prospect_name,
    'client_display_name', q.prospect_name, 'contact_person', q.prospect_contact_person,
    'phone', q.prospect_phone, 'email', q.prospect_email, 'tax_id', q.prospect_tax_id, 'address', q.prospect_address
  );
  v_matter := coalesce(q.matter_snapshot_json, '{}'::jsonb);

  select coalesce(jsonb_agg(jsonb_build_object(
    'quotation_item_id', i.id, 'description', i.description, 'quantity', i.quantity,
    'unit_price', i.unit_price, 'price_tax_mode', i.price_tax_mode,
    'vat_applicable', i.vat_applicable, 'vat_rate', i.vat_rate,
    'amount_before_tax', i.amount_before_tax, 'vat_amount', i.vat_amount,
    'line_total', i.line_total, 'sort_order', i.sort_order
  ) order by i.sort_order, i.id), '[]'::jsonb),
    coalesce(sum(i.amount_before_tax), 0), coalesce(sum(i.vat_amount), 0), coalesce(sum(i.line_total), 0)
  into v_items, v_item_before, v_item_vat, v_item_total
  from public.finance_quotation_items i where i.quotation_id = q.id;
  if jsonb_array_length(v_items) = 0 then raise exception 'Quotation requires at least one item'; end if;
  if exists (select 1 from public.finance_quotation_items i where i.quotation_id = q.id and (
    nullif(btrim(i.description), '') is null or i.quantity <= 0 or i.unit_price < 0 or
    i.amount_before_tax < 0 or i.vat_amount < 0 or i.line_total <> i.amount_before_tax + i.vat_amount or
    (not i.vat_applicable and (i.vat_rate <> 0 or i.vat_amount <> 0))
  )) then raise exception 'Quotation contains invalid line items'; end if;
  if v_item_before <> q.subtotal_vatable + q.subtotal_non_vatable or v_item_vat <> q.vat_amount or v_item_total <> q.grand_total then
    raise exception 'Quotation totals do not reconcile with line items';
  end if;

  select * into v_payment from public.finance_quotation_payment_terms where quotation_id = q.id for update;
  if v_payment.id is null then raise exception 'Payment terms are required'; end if;
  perform public.validate_finance_quotation_payment_terms(q.id, true);
  if v_payment.amount_before_tax <> q.subtotal_vatable + q.subtotal_non_vatable or v_payment.vat_amount <> q.vat_amount or v_payment.total_amount <> q.grand_total then
    raise exception 'Payment terms totals do not reconcile with the quotation';
  end if;

  select jsonb_build_object(
    'company_name_th', p.company_name_th, 'company_name_en', p.company_name_en, 'tax_id', p.tax_id,
    'branch_label', p.branch_label, 'address_th', p.address_th, 'phone', p.phone, 'email', p.email,
    'website', p.website, 'description', p.description, 'quotation_prefix', p.quotation_prefix,
    'logo_storage_path', p.logo_storage_path
  ) into v_company from public.finance_company_profiles p where p.id = 'default';
  v_company := coalesce(v_company, coalesce(q.document_data_snapshot_json->'company_profile', '{}'::jsonb));
  select jsonb_build_object('key', s.signer_key, 'name', s.display_name,
    'position', concat_ws(' / ', nullif(s.position_th, ''), nullif(s.position_en, '')),
    'email', s.email, 'signature_storage_path', s.signature_storage_path)
  into v_signer from public.finance_authorized_signers s where s.signer_key = q.authorized_signer_key;
  v_signer := coalesce(v_signer, jsonb_build_object('key', q.authorized_signer_key, 'name', q.authorized_signer_name, 'position', q.authorized_signer_position, 'email', q.authorized_signer_email));

  select coalesce(jsonb_agg(jsonb_build_object(
    'installment_no', pi.installment_no, 'title', pi.title, 'calculation_type', pi.calculation_type,
    'percentage', pi.percentage, 'trigger_type', pi.trigger_type, 'trigger_description', pi.trigger_description,
    'due_date', pi.due_date, 'payment_due_days', pi.payment_due_days, 'client_note', pi.client_note,
    'amount_before_tax', pi.amount_before_tax, 'vat_amount', pi.vat_amount, 'total_amount', pi.total_amount,
    'items', coalesce((select jsonb_agg(jsonb_build_object(
      'quotation_item_id', ai.quotation_item_id, 'description_snapshot', qi.description,
      'price_tax_mode', qi.price_tax_mode, 'vat_applicable', qi.vat_applicable, 'vat_rate', qi.vat_rate,
      'allocation_percentage', ai.allocation_percentage, 'allocated_amount_before_tax', ai.allocated_amount_before_tax,
      'allocated_vat_amount', ai.allocated_vat_amount, 'allocated_total', ai.allocated_total
    ) order by ai.sort_order, ai.id) from public.finance_quotation_payment_installment_items ai
      join public.finance_quotation_items qi on qi.id = ai.quotation_item_id where ai.payment_installment_id = pi.id), '[]'::jsonb)
  ) order by pi.installment_no), '[]'::jsonb)
  into v_installments from public.finance_quotation_payment_installments pi where pi.payment_terms_id = v_payment.id;

  select coalesce(nullif(btrim(up.staff_name), ''), nullif(btrim(up.full_name), ''), '')
    into v_actor_name from public.user_profiles up where up.id = auth.uid();
  v_snapshot := coalesce(q.document_data_snapshot_json, '{}'::jsonb) || jsonb_build_object(
    'version', 2,
    'quotation', jsonb_build_object('quotation_no', q.quotation_no, 'issue_date', q.issue_date, 'valid_until', q.valid_until, 'currency', 'THB', 'status_at_freeze', 'sent'),
    'client', v_client, 'matter', v_matter, 'company', v_company, 'company_profile', v_company,
    'commercial', jsonb_build_object('scope_of_legal_services', q.scope_of_legal_services, 'included_services', q.included_services, 'excluded_services', q.excluded_services, 'note', q.note, 'authorized_signer', v_signer),
    'authorized_signer', v_signer, 'items', v_items,
    'totals', jsonb_build_object('subtotal_vatable', q.subtotal_vatable, 'subtotal_non_vatable', q.subtotal_non_vatable, 'vat_amount', q.vat_amount, 'grand_total', q.grand_total),
    'payment_terms', jsonb_build_object('version', v_payment.snapshot_version, 'payment_method_type', v_payment.payment_method_type, 'allocation_mode', v_payment.allocation_mode, 'currency', v_payment.currency, 'client_summary', v_payment.client_summary, 'amount_before_tax', v_payment.amount_before_tax, 'vat_amount', v_payment.vat_amount, 'total_amount', v_payment.total_amount, 'installments', v_installments),
    'frozen_at', now(), 'frozen_by', jsonb_build_object('user_id', auth.uid(), 'email', '', 'name', coalesce(v_actor_name, ''))
  );

  update public.finance_quotations quotation set
    status = 'sent', document_data_snapshot_json = v_snapshot,
    sent_at = now(), sent_by_user_id = auth.uid(),
    updated_by_user_id = auth.uid(), updated_by_email = null, updated_by_name = v_actor_name, updated_at = now()
  where quotation.id = q.id;
  return q.id;
end;
$function$

CREATE OR REPLACE FUNCTION public.set_finance_quotation_status(p_quotation_id uuid, p_next_status text, p_cancel_reason text, p_user_id uuid, p_user_email text, p_user_name text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  q public.finance_quotations%rowtype;
  v_next_status text := lower(trim(coalesce(p_next_status, '')));
  v_item_before numeric(14,2);
  v_item_vat numeric(14,2);
  v_item_total numeric(14,2);
  v_payment public.finance_quotation_payment_terms%rowtype;
  v_client jsonb;
  v_matter jsonb := '{}'::jsonb;
  v_company jsonb := '{}'::jsonb;
  v_signer jsonb := '{}'::jsonb;
  v_items jsonb;
  v_installments jsonb;
  v_snapshot jsonb;
  v_actor_name text;
begin
  if not public.current_user_can_manage_finance_quotations() then
    raise exception 'Not allowed to update finance quotation status';
  end if;

  select * into q
  from public.finance_quotations
  where id = p_quotation_id
  for update;

  if q.id is null then raise exception 'Quotation not found'; end if;
  select coalesce(nullif(btrim(staff_name), ''), nullif(btrim(full_name), ''), '')
    into v_actor_name from public.user_profiles where id = auth.uid();
  if not ((q.status = 'draft' and v_next_status in ('sent', 'cancelled')) or (q.status = 'sent' and v_next_status in ('accepted', 'cancelled'))) then
    raise exception 'Invalid quotation status transition';
  end if;

  if q.status = 'draft' and v_next_status = 'sent' then
    if q.valid_until is not null and q.valid_until < q.issue_date then
      raise exception 'Valid until cannot be before issue date';
    end if;
    if q.case_id is not null and q.advisory_matter_id is not null then
      raise exception 'Select either case or advisory matter, not both';
    end if;

    select jsonb_build_object('id', c.id, 'name', c.name, 'tax_id', c.tax_id, 'address', c.address, 'phone', c.phone, 'email', c.email)
      into v_client from public.clients c where c.id = q.client_id;
    if v_client is null then raise exception 'Quotation client not found'; end if;

    if q.case_id is not null then
      select jsonb_build_object('type', 'case', 'id', c.id, 'file_no', c.file_no, 'title', c.title, 'client_name', c.client_name)
        into v_matter from public.cases c where c.id = q.case_id;
      if v_matter is null then raise exception 'Quotation case not found'; end if;
    elsif q.advisory_matter_id is not null then
      select jsonb_build_object('type', 'advisory_matter', 'id', a.id, 'matter_no', a.matter_no, 'title', a.title)
        into v_matter from public.advisory_matters a where a.id = q.advisory_matter_id;
      if v_matter is null then raise exception 'Quotation advisory matter not found'; end if;
    end if;

    select coalesce(jsonb_agg(jsonb_build_object(
      'quotation_item_id', i.id, 'description', i.description, 'quantity', i.quantity,
      'unit_price', i.unit_price, 'vat_applicable', i.vat_applicable, 'vat_rate', i.vat_rate,
      'amount_before_tax', i.amount_before_tax, 'vat_amount', i.vat_amount,
      'line_total', i.line_total, 'sort_order', i.sort_order
    ) order by i.sort_order, i.id), '[]'::jsonb),
      coalesce(sum(i.amount_before_tax), 0), coalesce(sum(i.vat_amount), 0), coalesce(sum(i.line_total), 0)
    into v_items, v_item_before, v_item_vat, v_item_total
    from public.finance_quotation_items i where i.quotation_id = q.id;

    if jsonb_array_length(v_items) = 0 then raise exception 'Quotation requires at least one item'; end if;
    if exists (select 1 from public.finance_quotation_items i where i.quotation_id = q.id and (
      nullif(btrim(i.description), '') is null or i.quantity <= 0 or i.unit_price < 0 or
      i.amount_before_tax < 0 or i.vat_amount < 0 or i.line_total <> i.amount_before_tax + i.vat_amount or
      (not i.vat_applicable and (i.vat_rate <> 0 or i.vat_amount <> 0))
    )) then raise exception 'Quotation contains invalid line items'; end if;
    if v_item_before <> q.subtotal_vatable + q.subtotal_non_vatable or v_item_vat <> q.vat_amount or v_item_total <> q.grand_total then
      raise exception 'Quotation totals do not reconcile with line items';
    end if;

    select * into v_payment from public.finance_quotation_payment_terms where quotation_id = q.id for update;
    if v_payment.id is null then raise exception 'Payment terms are required'; end if;
    perform public.validate_finance_quotation_payment_terms(q.id, true);
    if v_payment.amount_before_tax <> q.subtotal_vatable + q.subtotal_non_vatable or v_payment.vat_amount <> q.vat_amount or v_payment.total_amount <> q.grand_total then
      raise exception 'Payment terms totals do not reconcile with the quotation';
    end if;

    select jsonb_build_object(
      'company_name_th', p.company_name_th, 'company_name_en', p.company_name_en, 'tax_id', p.tax_id,
      'branch_label', p.branch_label, 'address_th', p.address_th, 'phone', p.phone, 'email', p.email,
      'website', p.website, 'description', p.description, 'quotation_prefix', p.quotation_prefix,
      'logo_storage_path', p.logo_storage_path
    ) into v_company from public.finance_company_profiles p where p.id = 'default';
    v_company := coalesce(v_company, coalesce(q.document_data_snapshot_json->'company_profile', '{}'::jsonb));
    select jsonb_build_object('key', s.signer_key, 'name', s.display_name,
      'position', concat_ws(' / ', nullif(s.position_th, ''), nullif(s.position_en, '')),
      'email', s.email, 'signature_storage_path', s.signature_storage_path)
      into v_signer from public.finance_authorized_signers s where s.signer_key = q.authorized_signer_key;
    v_signer := coalesce(v_signer, jsonb_build_object('key', q.authorized_signer_key, 'name', q.authorized_signer_name, 'position', q.authorized_signer_position, 'email', q.authorized_signer_email));

    select coalesce(jsonb_agg(jsonb_build_object(
      'installment_no', pi.installment_no, 'title', pi.title, 'calculation_type', pi.calculation_type,
      'percentage', pi.percentage, 'trigger_type', pi.trigger_type, 'trigger_description', pi.trigger_description,
      'due_date', pi.due_date, 'payment_due_days', pi.payment_due_days, 'client_note', pi.client_note,
      'amount_before_tax', pi.amount_before_tax, 'vat_amount', pi.vat_amount, 'total_amount', pi.total_amount,
      'items', coalesce((select jsonb_agg(jsonb_build_object(
        'quotation_item_id', ai.quotation_item_id, 'description_snapshot', qi.description,
        'vat_applicable', qi.vat_applicable, 'vat_rate', qi.vat_rate,
        'allocated_amount_before_tax', ai.allocated_amount_before_tax, 'allocated_vat_amount', ai.allocated_vat_amount,
        'allocated_total', ai.allocated_total
      ) order by ai.sort_order, ai.id) from public.finance_quotation_payment_installment_items ai
        join public.finance_quotation_items qi on qi.id = ai.quotation_item_id where ai.payment_installment_id = pi.id), '[]'::jsonb)
    ) order by pi.installment_no), '[]'::jsonb) into v_installments
    from public.finance_quotation_payment_installments pi where pi.payment_terms_id = v_payment.id;

    v_snapshot := coalesce(q.document_data_snapshot_json, '{}'::jsonb) || jsonb_build_object(
      'version', 2,
      'quotation', jsonb_build_object('quotation_no', q.quotation_no, 'issue_date', q.issue_date, 'valid_until', q.valid_until, 'currency', 'THB', 'status_at_freeze', 'sent'),
      'client', v_client, 'matter', v_matter, 'company', v_company,
      'company_profile', v_company,
      'commercial', jsonb_build_object('scope_of_legal_services', q.scope_of_legal_services, 'included_services', q.included_services, 'excluded_services', q.excluded_services, 'note', q.note, 'authorized_signer', v_signer),
      'authorized_signer', v_signer,
      'items', v_items,
      'totals', jsonb_build_object('subtotal_vatable', q.subtotal_vatable, 'subtotal_non_vatable', q.subtotal_non_vatable, 'vat_amount', q.vat_amount, 'grand_total', q.grand_total),
      'payment_terms', jsonb_build_object('version', v_payment.snapshot_version, 'payment_method_type', v_payment.payment_method_type, 'currency', v_payment.currency, 'client_summary', v_payment.client_summary, 'amount_before_tax', v_payment.amount_before_tax, 'vat_amount', v_payment.vat_amount, 'total_amount', v_payment.total_amount, 'installments', v_installments),
      'frozen_at', now(), 'frozen_by', jsonb_build_object('user_id', auth.uid(), 'email', '', 'name', coalesce(v_actor_name, ''))
    );
  end if;

  -- This SECURITY DEFINER lifecycle RPC bypasses ordinary RLS while FORCE RLS is disabled.
  -- Review this function before enabling FORCE ROW LEVEL SECURITY on finance_quotations.
  update public.finance_quotations set
    status = v_next_status,
    document_data_snapshot_json = case when q.status = 'draft' and v_next_status = 'sent' then v_snapshot else document_data_snapshot_json end,
    sent_at = case when v_next_status = 'sent' then now() else sent_at end,
    sent_by_user_id = case when v_next_status = 'sent' then auth.uid() else sent_by_user_id end,
    accepted_at = case when v_next_status = 'accepted' then now() else accepted_at end,
    accepted_by_user_id = case when v_next_status = 'accepted' then auth.uid() else accepted_by_user_id end,
    cancelled_at = case when v_next_status = 'cancelled' then now() else cancelled_at end,
    cancelled_by_user_id = case when v_next_status = 'cancelled' then auth.uid() else cancelled_by_user_id end,
    cancel_reason = case when v_next_status = 'cancelled' then nullif(trim(coalesce(p_cancel_reason, '')), '') else cancel_reason end,
    updated_by_user_id = auth.uid(), updated_by_email = null, updated_by_name = v_actor_name, updated_at = now()
  where id = q.id;
  return q.id;
end;
$function$

CREATE OR REPLACE FUNCTION public.set_finance_treasury_authority(p_user uuid, p_bank uuid, p_cash uuid, p_rights jsonb, p_version integer, p_reason text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare a public.finance_treasury_account_authorities%rowtype; before_row jsonb;
begin
 if not public.money_allocation_admin() then raise exception 'EXPENSE_ADMIN_REQUIRED'; end if;
 if nullif(btrim(p_reason),'') is null or not public.treasury_location_active(p_bank,p_cash)
  or not exists(select 1 from public.user_profiles where id=p_user and active and role not in ('partner','viewer'))
  or jsonb_typeof(p_rights) is distinct from 'object' then raise exception 'EXPENSE_AUTHORITY_INVALID'; end if;
 perform pg_advisory_xact_lock(hashtextextended('expense_authority:'||p_user,0));
 select * into a from public.finance_treasury_account_authorities where user_id=p_user
  and bank_account_id is not distinct from p_bank and cash_location_id is not distinct from p_cash for update;
 before_row:=to_jsonb(a);
 if a.version is distinct from p_version then raise exception 'EXPENSE_STALE'; end if;
 if a.id is null then
  insert into public.finance_treasury_account_authorities(user_id,bank_account_id,cash_location_id,view_balance,view_movements,record_outflow,confirm_outflow,updated_by)
  values(p_user,p_bank,p_cash,coalesce((p_rights->>'view_balance')::boolean,false),coalesce((p_rights->>'view_movements')::boolean,false),
   coalesce((p_rights->>'record_outflow')::boolean,false),coalesce((p_rights->>'confirm_outflow')::boolean,false),auth.uid()) returning * into a;
 else
  update public.finance_treasury_account_authorities set view_balance=coalesce((p_rights->>'view_balance')::boolean,false),
   view_movements=coalesce((p_rights->>'view_movements')::boolean,false),record_outflow=coalesce((p_rights->>'record_outflow')::boolean,false),
   confirm_outflow=coalesce((p_rights->>'confirm_outflow')::boolean,false),version=version+1,updated_at=clock_timestamp(),updated_by=auth.uid()
   where id=a.id returning * into a;
 end if;
 insert into public.finance_treasury_authority_audit(authority_id,version,actor_id,reason,evidence_json)
 values(a.id,a.version,auth.uid(),btrim(p_reason),jsonb_build_object('before',before_row,'after',to_jsonb(a)));
 return a.id;
end;
$function$

CREATE OR REPLACE FUNCTION public.tax_filing_account(p_bank uuid, p_cash uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare account jsonb;
begin
 if not public.treasury_location_active(p_bank,p_cash) or public.treasury_can_view(p_bank,p_cash) is distinct from true then raise exception 'TAX_FILING_ACCOUNT_REQUIRED'; end if;
 select to_jsonb(a) into account from public.finance_treasury_balances a where bank_account_id is not distinct from p_bank and cash_location_id is not distinct from p_cash;
 return account;
end;
$function$

CREATE OR REPLACE FUNCTION public.transition_finance_direct_money_receipt(p_id uuid, p_expected_version integer, p_action text, p_acknowledged boolean, p_reason text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare a public.finance_direct_money_receipts%rowtype; ts timestamptz:=clock_timestamp();
begin
 if not public.money_allocation_admin() then raise exception 'DIRECT_MONEY_PERMISSION_DENIED'; end if;
 if p_acknowledged is distinct from true then raise exception 'DIRECT_MONEY_ACK_REQUIRED'; end if;
 if p_action is null or p_action not in('confirm','reverse') then raise exception 'DIRECT_MONEY_TRANSITION_INVALID'; end if;
 perform pg_advisory_xact_lock(hashtextextended('direct_money:'||p_id::text,0));
 select * into a from public.finance_direct_money_receipts where id=p_id for update;
 if a.id is null then raise exception 'DIRECT_MONEY_MISSING'; end if;
 if a.version=p_expected_version+1 and ((p_action='confirm' and a.status='confirmed' and a.confirmed_by=auth.uid())
  or (p_action='reverse' and a.status='reversed' and a.reversed_by=auth.uid() and a.reversal_reason=btrim(p_reason))) then return a.id; end if;
 if a.version is distinct from p_expected_version then raise exception 'DIRECT_MONEY_STALE'; end if;
 if p_action='confirm' and a.status='draft' then
  perform public.direct_money_payload(a.input_json);
  a.status:='confirmed'; a.version:=a.version+1; a.updated_at:=ts; a.confirmed_at:=ts; a.confirmed_by:=auth.uid();
  update public.finance_direct_money_receipts set status=a.status,version=a.version,updated_at=ts,confirmed_at=ts,confirmed_by=auth.uid(),
    confirmed_snapshot_json=public.direct_money_snapshot(a) where id=a.id returning * into a;
 elsif p_action='reverse' and a.status='confirmed' then
  if nullif(btrim(p_reason),'') is null or length(p_reason)>2000 then raise exception 'DIRECT_MONEY_REASON_REQUIRED'; end if;
  if exists(select 1 from public.finance_vp_revenue_distributions where direct_money_receipt_id=a.id and status in('reviewed','finalized'))
  then raise exception 'VP_DISTRIBUTION_SUPERSEDE_REQUIRED'; end if;
  update public.finance_direct_money_receipts set status='reversed',version=version+1,updated_at=ts,reversed_at=ts,reversed_by=auth.uid(),reversal_reason=btrim(p_reason)
   where id=a.id returning * into a;
 else raise exception 'DIRECT_MONEY_TRANSITION_INVALID'; end if;
 insert into public.finance_direct_money_receipt_audit(receipt_id,event_type,version,actor_id,created_at,evidence_json)
 values(a.id,a.status,a.version,auth.uid(),ts,to_jsonb(a)); return a.id;
end;
$function$

CREATE OR REPLACE FUNCTION public.transition_finance_tax_filing(p_id uuid, p_version integer, p_action text, p_filed_on date, p_reference text, p_evidence text, p_acknowledged boolean)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare f public.finance_tax_filings%rowtype; s jsonb;
begin
 if public.tax_filing_can_manage() is distinct from true then raise exception 'TAX_FILING_PERMISSION_DENIED'; end if;
 if p_acknowledged is distinct from true then raise exception 'TAX_FILING_ACK_REQUIRED'; end if;
 perform pg_advisory_xact_lock(hashtextextended('payout_lifecycle',0)); perform pg_advisory_xact_lock(500050); perform pg_advisory_xact_lock(500052);
 select * into strict f from public.finance_tax_filings where id=p_id for update;
 if f.status=p_action then
  if p_action='filed' and (f.filed_on is distinct from p_filed_on or f.external_reference is distinct from btrim(p_reference) or f.filing_evidence is distinct from btrim(p_evidence))
   then raise exception 'TAX_FILING_IDEMPOTENCY_CONFLICT'; end if;
  return p_id;
 end if;
 if f.version is distinct from p_version or not ((f.status='draft' and p_action in ('ready_for_review','cancelled')) or (f.status='ready_for_review' and p_action in ('filed','cancelled')))
  or p_action is null then raise exception 'TAX_FILING_STALE'; end if;
 if p_action<>'cancelled' then
  s:=public.tax_filing_pool(f.period_month,f.filing_type);
  if md5(s::text)<>f.source_fingerprint then raise exception 'TAX_FILING_SOURCE_CHANGED'; end if;
  if (s->>'ready')::boolean is distinct from true or f.tax_amount is null then raise exception 'TAX_FILING_NOT_READY'; end if;
 end if;
 if p_action='filed' and (p_filed_on is null or p_filed_on<f.period_month or p_filed_on>(now() at time zone 'Asia/Bangkok')::date
  or nullif(btrim(p_reference),'') is null or nullif(btrim(p_evidence),'') is null) then raise exception 'TAX_FILING_EVIDENCE_REQUIRED'; end if;
 if p_action='cancelled' and (nullif(btrim(p_evidence),'') is null or length(p_evidence)>2000) then raise exception 'TAX_FILING_EVIDENCE_REQUIRED'; end if;
 update public.finance_tax_filings set status=p_action,version=version+1,
  filed_on=case when p_action='filed' then p_filed_on end,filed_at=case when p_action='filed' then clock_timestamp() end,filed_by=case when p_action='filed' then auth.uid() end,
  external_reference=case when p_action='filed' then btrim(p_reference) end,filing_evidence=case when p_action='filed' then btrim(p_evidence) end,
  filed_snapshot_json=case when p_action='filed' then jsonb_build_object('source',f.source_snapshot_json,'due_date',f.due_date,'due_date_evidence',f.due_date_evidence,
   'external_reference',btrim(p_reference),'filing_evidence',btrim(p_evidence),'filed_on',p_filed_on) end,
  cancelled_at=case when p_action='cancelled' then clock_timestamp() end,cancelled_by=case when p_action='cancelled' then auth.uid() end,cancellation_reason=case when p_action='cancelled' then btrim(p_evidence) end where id=p_id;
 insert into public.finance_tax_filing_audit(filing_id,event_type,version,actor_id,evidence_json)
 select id,p_action,version,auth.uid(),to_jsonb(x) from public.finance_tax_filings x where id=p_id;
 return p_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.transition_finance_tax_remittance(p_id uuid, p_version integer, p_action text, p_acknowledged boolean)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare r public.finance_tax_remittances%rowtype; account jsonb; snapshot jsonb; cash uuid; ts timestamptz:=clock_timestamp();
begin
 if public.tax_filing_can_remit() is distinct from true then raise exception 'TAX_FILING_PERMISSION_DENIED'; end if;
 if p_acknowledged is distinct from true then raise exception 'TAX_FILING_ACK_REQUIRED'; end if;
 perform pg_advisory_xact_lock(500052);
 select * into strict r from public.finance_tax_remittances where id=p_id for update;
 if r.status=p_action and p_action in ('confirmed','cancelled') then return r.id; end if;
 if r.status<>'draft' or r.version is distinct from p_version or p_action is null or p_action not in ('confirmed','cancelled') then raise exception 'TAX_FILING_STALE'; end if;
 if p_action='confirmed' then
  perform pg_advisory_xact_lock(hashtextextended('finance_cash_cutover:THB',0));
  account:=public.tax_filing_account(r.bank_account_id,r.cash_location_id);
  if account->>'opening_id' is null or account->>'system_balance' is null then raise exception 'FINANCE_CASH_OPENING_BALANCE_REQUIRED'; end if;
  if public.finance_bangkok_completed_day_end(r.paid_on)<=(account->>'opening_as_of')::timestamptz then raise exception 'FINANCE_CASH_TRANSACTION_BEFORE_CUTOVER'; end if;
  if account is distinct from r.draft_snapshot_json->'account' then raise exception 'TAX_FILING_ACCOUNT_CHANGED'; end if;
  snapshot:=r.draft_snapshot_json||jsonb_build_object('paid_on',r.paid_on,'reference',r.external_reference,'evidence',r.payment_evidence,
   'actual_cash_paid',r.amount,'balance_before',(account->>'system_balance')::numeric,'balance_after',(account->>'system_balance')::numeric-r.amount);
  update public.finance_tax_remittances set status='confirmed',version=version+1,confirmed_at=ts,confirmed_by=auth.uid(),confirmed_snapshot_json=snapshot where id=p_id;
  insert into public.finance_cash_transactions(occurred_at,direction,transaction_type,bank_account_id,cash_location_id,cash_amount,currency,status,
   source_tax_remittance_id,reference_no,description,created_by_user_id,updated_by_user_id,confirmed_at,confirmed_by_user_id)
  values(public.finance_bangkok_completed_day_end(r.paid_on),'outflow','other',r.bank_account_id,r.cash_location_id,r.amount,'THB','confirmed',r.id,
   r.external_reference,'Tax remittance',auth.uid(),auth.uid(),ts,auth.uid()) returning id into cash;
  perform public.record_finance_cash_transaction_audit_event(cash,'confirmed',jsonb_build_object('tax_remittance_id',r.id,'remittance',snapshot));
 else
  update public.finance_tax_remittances set status='cancelled',version=version+1,cancelled_at=ts,cancelled_by=auth.uid() where id=p_id;
 end if;
 insert into public.finance_tax_remittance_audit(remittance_id,event_type,version,actor_id,evidence_json)
 select id,p_action,version,auth.uid(),to_jsonb(x) from public.finance_tax_remittances x where id=p_id;
 return p_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.transition_finance_vp_distribution(p_id uuid, p_expected_version integer, p_source jsonb, p_action text, p_acknowledged boolean, p_reason text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare a public.finance_vp_revenue_distributions%rowtype; s jsonb; ev text; ts timestamptz;
begin
 if not public.money_allocation_admin() then raise exception 'VP_DISTRIBUTION_PERMISSION_DENIED'; end if;
 if p_acknowledged is distinct from true then raise exception 'VP_DISTRIBUTION_ACK_REQUIRED'; end if;
 if p_action is null or p_action not in ('review','finalize','supersede') then raise exception 'VP_DISTRIBUTION_TRANSITION_INVALID'; end if;
 if p_expected_version is null or p_expected_version<1 then raise exception 'VP_DISTRIBUTION_STALE'; end if;
 select * into a from public.finance_vp_revenue_distributions where id=p_id;
 if a.id is null then raise exception 'VP_DISTRIBUTION_MISSING'; end if;
 perform public.vp_received_lock(a.payment_id,a.direct_money_receipt_id);
 select * into a from public.finance_vp_revenue_distributions where id=p_id for update;
 if p_action='supersede' then
  if nullif(btrim(p_reason),'') is null or length(p_reason)>2000 then raise exception 'VP_DISTRIBUTION_REASON_REQUIRED'; end if;
  -- Retirement must remain possible when the live source is stale or unreadable.
  if a.status='superseded' and a.version=p_expected_version+1 and a.supersede_reason=btrim(p_reason) then return a.id; end if;
 else
  s:=public.vp_received_source(a.payment_id,a.direct_money_receipt_id);
  if s is distinct from p_source or s is distinct from a.source_snapshot_json then raise exception 'VP_DISTRIBUTION_SOURCE_CHANGED'; end if;
  if s->'blockers' is distinct from '[]'::jsonb or jsonb_array_length(s->'lines')=0 then raise exception 'VP_DISTRIBUTION_SOURCE_UNPROVEN'; end if;
  perform public.vp_distribution_choices(s,a.decisions_json,true);
  if a.version=p_expected_version+1 and ((p_action='review' and a.status='reviewed') or (p_action='finalize' and a.status='finalized')) then return a.id; end if;
 end if;
 if a.version is distinct from p_expected_version then raise exception 'VP_DISTRIBUTION_STALE'; end if;
 ts:=clock_timestamp();
 if p_action='supersede' and a.status<>'superseded' then
  update public.finance_vp_revenue_distributions set status='superseded',version=version+1,updated_at=ts,
   superseded_at=ts,superseded_by=auth.uid(),supersede_reason=btrim(p_reason) where id=a.id returning * into a; ev:='superseded';
 elsif p_action='review' and a.status='draft' then
  update public.finance_vp_revenue_distributions set status='reviewed',version=version+1,updated_at=ts,
   reviewed_at=ts,reviewed_by=auth.uid() where id=a.id returning * into a; ev:='reviewed';
 elsif p_action='finalize' and a.status='reviewed' then
  update public.finance_vp_revenue_distributions set status='finalized',version=version+1,updated_at=ts,
   finalized_at=ts,finalized_by=auth.uid() where id=a.id returning * into a; ev:='finalized';
 else raise exception 'VP_DISTRIBUTION_TRANSITION_INVALID'; end if;
 insert into public.finance_vp_revenue_distribution_audit(distribution_id,event_type,actor_id,created_at,evidence_json)
 values(a.id,ev,auth.uid(),ts,to_jsonb(a));
 return a.id;
end;
$function$

CREATE OR REPLACE FUNCTION public.void_finance_invoice(p_invoice_id uuid, p_reason text, p_acknowledged boolean)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_invoice public.finance_invoices%rowtype;
  v_after public.finance_invoices%rowtype;
  v_bridge public.finance_billing_installment_charge_bridges%rowtype;
  v_installment public.finance_billing_installments%rowtype;
  v_plan public.finance_billing_plans%rowtype;
  v_reason text:=nullif(btrim(coalesce(p_reason,'')),'');
  v_now timestamptz:=now();
  v_draft_payments integer;
  v_confirmed_payments integer;
  v_settled numeric(14,2);
begin
  select * into v_invoice from public.finance_invoices where id=p_invoice_id;
  if v_invoice.source_model='installment_v1' then return public.void_finance_invoice_v1_internal(p_invoice_id,p_reason,p_acknowledged); end if;
  if not public.current_user_can_manage_finance_quotations() or not public.current_user_can_manage_finance_billable_charges() then raise exception 'Not allowed to void Invoice V2'; end if;
  if v_reason is null or length(v_reason)>2000 then raise exception 'Valid Invoice Void reason is required'; end if;
  if p_acknowledged is distinct from true then raise exception 'Invoice Void acknowledgement is required'; end if;
  select * into v_invoice from public.finance_invoices where id=p_invoice_id for update;
  if v_invoice.id is null or v_invoice.source_model<>'billable_charge_v2' or v_invoice.document_status<>'issued' then raise exception 'Only an Issued Invoice V2 can be voided'; end if;
  select count(*) into v_draft_payments from public.finance_payment_invoice_allocations allocation join public.finance_payments payment on payment.id=allocation.payment_id where allocation.invoice_id=v_invoice.id and payment.status='draft';
  select count(*) into v_confirmed_payments from public.finance_payment_effective_invoice_allocations effective join public.finance_payments payment on payment.id=effective.payment_id where effective.invoice_id=v_invoice.id and payment.status='confirmed';
  select economically_settled_amount into v_settled from public.finance_invoice_settlement_summary where invoice_id=v_invoice.id;
  if v_settled is null then raise exception 'Invoice settlement summary is unavailable'; end if;
  if v_draft_payments>0 then raise exception 'Invoice has an active Payment Draft that must be cancelled before Void'; end if;
  if v_confirmed_payments>0 or v_settled<>0 then raise exception 'Invoice has effective Confirmed Payment settlement and cannot be voided'; end if;
  perform public.assert_finance_invoice_has_no_void_dependencies(v_invoice.id);
  if v_invoice.v2_bridge_id is not null then
    select * into v_bridge from public.finance_billing_installment_charge_bridges where id=v_invoice.v2_bridge_id;
    select * into v_plan from public.finance_billing_plans where id=v_bridge.billing_plan_id for update;
    select * into v_installment from public.finance_billing_installments where id=v_bridge.billing_installment_id for update;
    if v_installment.status<>'invoiced' then raise exception 'Bridged Billing Installment is not invoiced'; end if;
  end if;
  perform 1 from public.finance_invoice_charge_allocations where invoice_id=v_invoice.id and status='invoiced' order by billable_charge_id for update;
  perform 1 from public.finance_billable_charges where id in(select billable_charge_id from public.finance_invoice_charge_allocations where invoice_id=v_invoice.id and status='invoiced') order by id for update;
  perform public.validate_finance_invoice_integrity(v_invoice.id);
  perform set_config('vp.invoice_v2_lifecycle','void',true);
  update public.finance_invoices set document_status='voided',voided_at=v_now,voided_by_user_id=auth.uid(),void_reason=v_reason,updated_at=v_now,updated_by_user_id=auth.uid() where id=v_invoice.id;
  select * into v_after from public.finance_invoices where id=v_invoice.id;
  if v_after.invoice_no is distinct from v_invoice.invoice_no or v_after.issued_snapshot_json is distinct from v_invoice.issued_snapshot_json or v_after.total_amount is distinct from v_invoice.total_amount then raise exception 'Invoice Void must preserve issued evidence'; end if;
  update public.finance_invoice_charge_allocations set status='released',released_at=v_now,released_by_user_id=auth.uid(),release_reason=v_reason where invoice_id=v_invoice.id and status='invoiced';
  update public.finance_billable_charges charge set status='ready_to_invoice',updated_at=v_now,updated_by_user_id=auth.uid() where exists(select 1 from public.finance_invoice_charge_allocations allocation where allocation.invoice_id=v_invoice.id and allocation.billable_charge_id=charge.id and allocation.status='released' and allocation.released_at=v_now);
  if v_bridge.id is not null then
    update public.finance_billing_installments set status='ready_to_invoice',invoiced_at=null,updated_at=v_now,updated_by_user_id=auth.uid() where id=v_installment.id;
    if v_plan.status='completed' then update public.finance_billing_plans set status='active',updated_at=v_now,updated_by_user_id=auth.uid() where id=v_plan.id; end if;
    insert into public.finance_billing_installment_audit_events(billing_installment_id,billing_plan_id,event_type,event_payload_json,actor_user_id)
      values(v_installment.id,v_plan.id,'invoice_voided_reopened',jsonb_build_object('schema_version',2,'invoice_id',v_invoice.id,'invoice_no',v_invoice.invoice_no,'bridge_id',v_bridge.id,'v1_eligibility_restored',false),auth.uid());
  end if;
  insert into public.finance_invoice_audit_events(invoice_id,event_type,event_payload_json,actor_user_id)
    values(v_invoice.id,'voided',jsonb_build_object('schema_version',2,'source_model','billable_charge_v2','reason',v_reason,'bridge_preserved',v_bridge.id is not null,'charges_returned_ready',true,'v1_eligibility_restored',false,'effective_payment_settlement_at_void',0),auth.uid());
  perform public.validate_finance_invoice_integrity(v_invoice.id);
  perform public.validate_finance_invoice_payment_settlement(v_invoice.id);
  return v_invoice.id;
end;
$function$

CREATE OR REPLACE FUNCTION public.confirm_finance_treasury_transfer(p_id uuid, p_from_bank uuid, p_from_cash uuid, p_to_bank uuid, p_to_cash uuid, p_amount numeric, p_date date, p_note text, p_acknowledged boolean)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare t public.finance_treasury_transfers%rowtype; leg text; cash uuid; bank uuid; location uuid; opening public.finance_account_opening_balances%rowtype;
begin
 if public.statement_transfer_allowed(p_from_bank,p_from_cash,p_to_bank,p_to_cash) is distinct from true then raise exception 'STATEMENT_TRANSFER_PERMISSION_DENIED'; end if;
 if p_acknowledged is distinct from true then raise exception 'STATEMENT_TRANSFER_ACK_REQUIRED'; end if;
 if p_id is null or p_amount is null or p_amount<=0 or p_amount<>round(p_amount,2) or p_amount='NaN'::numeric
  or p_date is null or p_date>(current_timestamp at time zone 'Asia/Bangkok')::date or p_note is null or length(p_note)>2000
  or num_nonnulls(p_from_bank,p_from_cash)<>1 or num_nonnulls(p_to_bank,p_to_cash)<>1
  or (p_from_bank is not distinct from p_to_bank and p_from_cash is not distinct from p_to_cash) then raise exception 'STATEMENT_TRANSFER_INPUT_INVALID'; end if;
 perform pg_advisory_xact_lock(hashtextextended('treasury_transfer:'||p_id,0));
 select * into t from public.finance_treasury_transfers where id=p_id;
 if t.id is not null then
  if t.from_bank_id is not distinct from p_from_bank and t.from_cash_id is not distinct from p_from_cash
   and t.to_bank_id is not distinct from p_to_bank and t.to_cash_id is not distinct from p_to_cash
   and t.amount=p_amount and t.transferred_on=p_date and t.note=btrim(p_note) and t.confirmed_by=auth.uid() then return p_id; end if;
  raise exception 'STATEMENT_IDEMPOTENCY_CONFLICT';
 end if;
 -- Existing cutover lock serializes openings and actual money confirmation.
 perform pg_advisory_xact_lock(hashtextextended('finance_cash_cutover:THB',0));
 perform 1 from public.finance_bank_accounts where id in (p_from_bank,p_to_bank) order by id for share;
 perform 1 from public.finance_cash_locations where id in (p_from_cash,p_to_cash) order by id for share;
 if not public.treasury_location_active(p_from_bank,p_from_cash) or not public.treasury_location_active(p_to_bank,p_to_cash) then raise exception 'STATEMENT_TRANSFER_ACCOUNT_INVALID'; end if;
 foreach leg in array array['outflow','inflow'] loop
  bank:=case leg when 'outflow' then p_from_bank else p_to_bank end; location:=case leg when 'outflow' then p_from_cash else p_to_cash end;
  select * into opening from public.finance_account_opening_balances where bank_account_id is not distinct from bank and cash_location_id is not distinct from location and currency='THB' and status='confirmed' for update;
  if opening.id is null then raise exception 'FINANCE_CASH_OPENING_BALANCE_REQUIRED'; end if;
  if public.finance_bangkok_completed_day_end(p_date)<=opening.as_of then raise exception 'FINANCE_CASH_TRANSACTION_BEFORE_CUTOVER'; end if;
 end loop;
 insert into public.finance_treasury_transfers(id,from_bank_id,from_cash_id,to_bank_id,to_cash_id,amount,transferred_on,note,confirmed_by)
 values(p_id,p_from_bank,p_from_cash,p_to_bank,p_to_cash,p_amount,p_date,btrim(p_note),auth.uid()) returning * into t;
 foreach leg in array array['outflow','inflow'] loop
  insert into public.finance_cash_transactions(occurred_at,direction,transaction_type,bank_account_id,cash_location_id,cash_amount,currency,status,reference_no,description,created_by_user_id,updated_by_user_id,confirmed_at,confirmed_by_user_id)
  values(public.finance_bangkok_completed_day_end(p_date),leg,'transfer',case leg when 'outflow' then p_from_bank else p_to_bank end,
   case leg when 'outflow' then p_from_cash else p_to_cash end,p_amount,'THB','confirmed',t.reference,'Inter-account transfer',auth.uid(),auth.uid(),t.confirmed_at,auth.uid()) returning id into cash;
  insert into public.finance_treasury_transfer_legs values(p_id,leg,cash);
  perform public.record_finance_cash_transaction_audit_event(cash,'confirmed',jsonb_build_object('transfer',to_jsonb(t),'direction',leg,'company_economic_effect',0));
 end loop;
 return p_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.confirm_finance_vp_received_distribution(p_payment_id uuid, p_direct_id uuid, p_expected_id uuid, p_expected_version integer, p_source jsonb, p_choices jsonb, p_note text, p_acknowledged boolean)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare d public.finance_vp_revenue_distributions%rowtype; prior public.finance_vp_revenue_distributions%rowtype; canonical jsonb; result uuid;
begin
 if not public.money_allocation_admin() then raise exception 'VP_DISTRIBUTION_PERMISSION_DENIED'; end if;
 if p_acknowledged is distinct from true then raise exception 'VP_DISTRIBUTION_ACK_REQUIRED'; end if;
 if (p_expected_id is null)<>(p_expected_version is null) or p_expected_version<1 then raise exception 'VP_DISTRIBUTION_STALE'; end if;
 perform public.vp_received_lock(p_payment_id,p_direct_id);
 if p_source is distinct from public.vp_received_source(p_payment_id,p_direct_id) or p_source->'blockers' is distinct from '[]'::jsonb
 then raise exception 'VP_DISTRIBUTION_SOURCE_CHANGED'; end if;
 canonical:=public.vp_distribution_choices(p_source,p_choices,true);
 select * into d from public.finance_vp_revenue_distributions where payment_id is not distinct from p_payment_id
  and direct_money_receipt_id is not distinct from p_direct_id and status<>'superseded' for update;
 if d.status='finalized' then
  -- Immediate identical retry only; an unrelated/stale confirmation cannot be accepted.
  if d.source_snapshot_json=p_source and d.decisions_json=canonical and d.note=btrim(p_note) and d.finalized_by=auth.uid() then
   if d.version=3 and d.created_by=auth.uid() then
    select * into prior from public.finance_vp_revenue_distributions where id=d.previous_id;
    if (d.revision=1 and p_expected_id is null) or (d.previous_id=p_expected_id and prior.status='superseded' and prior.version=p_expected_version) then return d.id; end if;
   end if;
   if p_expected_id=d.id and exists(select 1 from public.finance_vp_revenue_distribution_audit a where a.distribution_id=d.id
    and (a.evidence_json->>'version')::integer=p_expected_version
    and ((a.evidence_json->>'status'='reviewed' and d.version=p_expected_version+1)
      or (a.evidence_json->>'status'='draft' and d.version in(p_expected_version+2,p_expected_version+3)))) then return d.id; end if;
  end if;
  raise exception 'VP_DISTRIBUTION_STALE';
 end if;
 if d.status='reviewed' then
  if d.id is distinct from p_expected_id or d.version is distinct from p_expected_version or d.decisions_json is distinct from canonical or d.note is distinct from btrim(p_note)
  then raise exception 'VP_DISTRIBUTION_STALE'; end if;
 else
  result:=public.save_finance_vp_received_distribution(p_payment_id,p_direct_id,p_expected_id,p_expected_version,p_source,canonical,p_note);
  select * into d from public.finance_vp_revenue_distributions where id=result;
  perform public.transition_finance_vp_distribution(d.id,d.version,p_source,'review',true,'');
  select * into d from public.finance_vp_revenue_distributions where id=result;
 end if;
 -- Existing trigger materializes rights; no payout, cash or Company Statement event.
 return public.transition_finance_vp_distribution(d.id,d.version,p_source,'finalize',true,'');
end;
$function$

CREATE OR REPLACE FUNCTION public.get_finance_distribution_payment_context(p_distribution_id uuid, p_entitlement_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare e public.finance_payable_entitlements%rowtype; w jsonb;
begin
 if not public.money_allocation_admin() then raise exception 'PAYOUT_PERMISSION_DENIED'; end if;
 select * into e from public.finance_payable_entitlements where id=p_entitlement_id and distribution_id=p_distribution_id and status='open';
 if e.id is null or not exists(select 1 from public.finance_vp_revenue_distributions where id=p_distribution_id and status='finalized')
  or exists(select 1 from public.finance_payout_allocations where entitlement_id=e.id) then raise exception 'PAYOUT_RIGHTS_UNAVAILABLE'; end if;
 perform public.payable_assert_distribution(p_distribution_id);
 w:=public.get_finance_payout_workspace(e.recipient_id,null);
 return jsonb_build_object('component',to_jsonb(e),'payee',(select p from jsonb_array_elements(w->'payees') p where p->>'id'=e.recipient_id::text),
  'accounts',w->'accounts','wht_treatment',null,'wht_rate',null);
 -- Recipient identity/entity/Tax ID do not establish an outgoing WHT rate. No history-based rate inference.
end;
$function$

CREATE OR REPLACE FUNCTION public.get_finance_expense_economics(p_expense uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare c jsonb; d public.finance_expense_economic_decisions%rowtype;
begin
 if not public.expense_can_read(p_expense) then raise exception 'EXPENSE_PERMISSION_DENIED'; end if;
 c:=public.statement_expense_context(p_expense);
 select * into d from public.finance_expense_economic_decisions where expense_id=p_expense order by revision desc limit 1;
 return jsonb_build_object('context',c,'decision',to_jsonb(d),'effective',d.id is not null and d.approved_recoverable_vat is not null and d.context_json=c,
  'can_manage',public.expense_can_manage());
end;
$function$

CREATE OR REPLACE FUNCTION public.get_finance_revenue_distribution_detail(p_source_type text, p_source_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare context jsonb;
begin
 if not public.current_user_can_view_finance_payments() then raise exception 'VP_DISTRIBUTION_PERMISSION_DENIED'; end if;
 if p_source_type='payment' then context:=public.get_finance_vp_formula_context(p_source_id);
 elsif p_source_type='direct_money_receipt' then context:=public.get_finance_direct_vp_formula_context(p_source_id);
 else raise exception 'VP_DISTRIBUTION_SOURCE_UNPROVEN'; end if;
 return context||jsonb_build_object('summary',public.vp_distribution_workspace_row(p_source_type,p_source_id),
  'participants',(select coalesce(jsonb_agg(jsonb_build_object('id',e.id,'source_line_id',e.source_line_id,'component_no',e.component_no,
   'recipient_id',e.recipient_id,'gross_amount',e.gross_amount,'payout_id',p.id,'paid_on',p.paid_on,'net_amount',p.net_amount,'wht_amount',p.wht_amount,
   'account',coalesce(p.confirmed_snapshot_json#>>'{account,name_th}',p.confirmed_snapshot_json#>>'{account,name_en}')) order by e.source_line_id,e.component_no),'[]')
   from public.finance_payable_entitlements e left join public.finance_payout_allocations a on a.entitlement_id=e.id
   left join public.finance_payouts p on p.id=a.payout_id and p.status='confirmed'
   where e.distribution_id=(context#>>'{current,id}')::uuid and e.status='open'));
end;
$function$

CREATE OR REPLACE FUNCTION public.get_finance_statement_accounts()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
 if not public.current_user_can_view_finance_cash_transactions() then raise exception 'TREASURY_PERMISSION_DENIED'; end if;
 return jsonb_build_object('can_transfer',public.current_user_can_manage_finance_cash_transactions() and public.current_user_can_confirm_finance_cash_transactions(),
  'can_manage_openings',public.money_allocation_admin(),
  'accounts',(select coalesce(jsonb_agg(to_jsonb(a) order by kind,name_th,account_id),'[]') from public.finance_treasury_accounts a));
end;
$function$

CREATE OR REPLACE FUNCTION public.pay_finance_distribution_participant(p_distribution_id uuid, p_entitlement_id uuid, p_request_id uuid, p_expected_payee_version integer, p_paid_on date, p_bank_account_id uuid, p_cash_location_id uuid, p_treatment text, p_rate numeric, p_note text, p_acknowledged boolean)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare e public.finance_payable_entitlements%rowtype; d public.finance_vp_revenue_distributions%rowtype;
 p public.finance_payouts%rowtype; payee public.finance_payees%rowtype; choice jsonb; dest uuid;
begin
 if not public.money_allocation_admin() then raise exception 'PAYOUT_PERMISSION_DENIED'; end if;
 if p_acknowledged is distinct from true then raise exception 'PAYOUT_ACK_REQUIRED'; end if;
 if p_request_id is null or p_note is null or length(p_note)>2000 then raise exception 'PAYOUT_INPUT_INVALID'; end if;
 if p_treatment is null or p_rate is null or p_rate<>round(p_rate,4)
  or not ((p_treatment='none' and p_rate=0) or (p_treatment='withhold' and p_rate>0 and p_rate<100)) then raise exception 'PAYOUT_WHT_REQUIRED'; end if;
 perform pg_advisory_xact_lock(hashtextextended('payout_lifecycle',0));
 select * into e from public.finance_payable_entitlements where id=p_entitlement_id and distribution_id=p_distribution_id;
 if e.id is null then raise exception 'PAYOUT_RIGHTS_UNAVAILABLE'; end if;
 -- Identical completed request retry is accepted before mutable master-data revalidation.
 select * into p from public.finance_payouts where id=p_request_id;
 if p.id is not null then
  if p.status='confirmed' and p.source_model='revenue_distribution_v1' and p.confirmed_snapshot_json->>'entry_point'='distribution_participant'
   and p.payee_id=e.recipient_id and p.paid_on=p_paid_on and p.bank_account_id is not distinct from p_bank_account_id
   and p.cash_location_id is not distinct from p_cash_location_id and p.note=p_note
   and jsonb_array_length(p.choices_json)=1 and p.choices_json#>>'{0,entitlement_id}'=e.id::text
   and p.choices_json#>>'{0,treatment}'=p_treatment and (p.choices_json#>>'{0,rate}')::numeric=p_rate then return p.id; end if;
  raise exception 'PAYOUT_STALE';
 end if;
 perform public.vp_received_lock(case when e.source_type='payment' then e.received_money_id end,case when e.source_type='direct_money_receipt' then e.received_money_id end);
 select * into d from public.finance_vp_revenue_distributions where id=p_distribution_id for update;
 select * into e from public.finance_payable_entitlements where id=p_entitlement_id for update;
 if d.status<>'finalized' or e.status<>'open' or exists(select 1 from public.finance_payout_allocations where entitlement_id=e.id)
 then raise exception 'PAYOUT_RIGHTS_UNAVAILABLE'; end if;
 perform public.payable_assert_distribution(d.id);
 -- Same deterministic internal identity as existing Payee save. Nothing is created on a read.
 perform pg_advisory_xact_lock(hashtextextended('payee:'||e.recipient_id,0));
 select * into payee from public.finance_payees where id=e.recipient_id for share;
 if payee.version is distinct from p_expected_payee_version then raise exception 'PAYOUT_STALE'; end if;
 if payee.id is null then
  if e.recipient_type<>'user' then raise exception 'PAYOUT_PAYEE_INVALID'; end if;
  perform public.save_finance_payee(e.recipient_id,e.recipient_id,'{}',null);
  select * into payee from public.finance_payees where id=e.recipient_id for share;
 end if;
 choice:=jsonb_build_array(jsonb_build_object('entitlement_id',e.id,'treatment',p_treatment,'rate',p_rate));
 perform public.save_finance_payout(p_request_id,e.recipient_id,p_paid_on,p_bank_account_id,p_cash_location_id,choice,p_note,null);
 select id into dest from public.finance_payee_destinations where payee_id=e.recipient_id and is_active;
 return public.payout_confirm_distribution_outflow(p_request_id,1,payee.version,dest,true,true);
end;
$function$

CREATE OR REPLACE FUNCTION public.payout_confirm_distribution_outflow(p_id uuid, p_expected_version integer, p_expected_payee_version integer, p_expected_destination_id uuid, p_acknowledged boolean, p_actual_outflow_only boolean)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare p public.finance_payouts%rowtype; payee public.finance_payees%rowtype; dest public.finance_payee_destinations%rowtype;
 opening public.finance_account_opening_balances%rowtype; r record; c jsonb; canonical jsonb; snapshot jsonb; allocation uuid; cash uuid; account jsonb;ts timestamptz:=clock_timestamp();
begin
 if not public.payout_can_manage() then raise exception 'PAYOUT_PERMISSION_DENIED'; end if;
 if p_acknowledged is distinct from true then raise exception 'PAYOUT_ACK_REQUIRED'; end if;
 perform pg_advisory_xact_lock(hashtextextended('payout_lifecycle',0));
 select * into p from public.finance_payouts where id=p_id;
 if p.id is null or p.source_model<>'revenue_distribution_v1' then raise exception 'PAYOUT_INPUT_INVALID'; end if;
 if p.status='confirmed' then return p.id; end if;
 -- Source -> distribution -> rights -> payout: same order as supersession.
 for r in select distinct e.source_type,e.received_money_id from public.finance_payable_entitlements e
  where e.id in(select (x->>'entitlement_id')::uuid from jsonb_array_elements(p.choices_json) x) order by 1,2 loop
  perform public.vp_received_lock(case when r.source_type='payment' then r.received_money_id end,case when r.source_type='direct_money_receipt' then r.received_money_id end);
 end loop;
 perform 1 from public.finance_vp_revenue_distributions where id in(select (x#>>'{entitlement,distribution_id}')::uuid from jsonb_array_elements(p.choices_json) x) order by id for update;
 perform 1 from public.finance_payable_entitlements where id in(select (x->>'entitlement_id')::uuid from jsonb_array_elements(p.choices_json) x) order by id for update;
 select * into p from public.finance_payouts where id=p_id for update;
 if p.status<>'draft' or p.version is distinct from p_expected_version then raise exception 'PAYOUT_STALE'; end if;
 canonical:=public.payout_choices(p.payee_id,(select jsonb_agg(jsonb_build_object('entitlement_id',x->'entitlement_id','treatment',x->'treatment','rate',x->'rate')) from jsonb_array_elements(p.choices_json) x));
 if canonical is distinct from p.choices_json then raise exception 'PAYOUT_STALE'; end if;
 select * into payee from public.finance_payees where id=p.payee_id for share;
 if not payee.is_active or payee.version is distinct from p_expected_payee_version or (payee.profile_id is not null and not exists(select 1 from public.user_profiles where id=payee.profile_id and active))
 then raise exception 'PAYOUT_PAYEE_INVALID'; end if;
 select * into dest from public.finance_payee_destinations where payee_id=payee.id and is_active for share;
 if not p_actual_outflow_only and p.bank_account_id is not null and (dest.id is null or dest.id is distinct from p_expected_destination_id) then raise exception 'PAYOUT_DESTINATION_REQUIRED'; end if;
 if p.wht_amount>0 and payee.tax_id is null then raise exception 'PAYOUT_TAX_ID_REQUIRED'; end if;
 perform pg_advisory_xact_lock(hashtextextended('finance_cash_cutover:THB',0));
 if not public.treasury_location_active(p.bank_account_id,p.cash_location_id) or not public.treasury_can_view(p.bank_account_id,p.cash_location_id) then raise exception 'PAYOUT_ACCOUNT_REQUIRED'; end if;
 select * into opening from public.finance_account_opening_balances where bank_account_id is not distinct from p.bank_account_id
  and cash_location_id is not distinct from p.cash_location_id and currency='THB' and status='confirmed' for update;
 if opening.id is null then raise exception 'FINANCE_CASH_OPENING_BALANCE_REQUIRED'; end if;
 if public.finance_bangkok_completed_day_end(p.paid_on)<=opening.as_of then raise exception 'FINANCE_CASH_TRANSACTION_BEFORE_CUTOVER'; end if;
 select to_jsonb(a) into account from public.finance_treasury_balances a where a.bank_account_id is not distinct from p.bank_account_id and a.cash_location_id is not distinct from p.cash_location_id;
 snapshot:=jsonb_build_object('schema_version',1,'payee',to_jsonb(payee),'destination',case when p.bank_account_id is not null and dest.id is not null then to_jsonb(dest) end,
  'account',account,'opening',to_jsonb(opening),'choices',canonical,'gross',p.gross_amount,'wht',p.wht_amount,'net',p.net_amount,'paid_on',p.paid_on,'currency','THB');
 if p_actual_outflow_only then snapshot:=snapshot||jsonb_build_object('entry_point','distribution_participant','actual_company_cash_moved',true); end if;
 update public.finance_payouts set status='confirmed',version=version+1,confirmed_snapshot_json=snapshot,confirmed_at=ts,confirmed_by=auth.uid(),updated_by=auth.uid(),updated_at=ts where id=p.id;
 for c in select value from jsonb_array_elements(canonical) loop
  insert into public.finance_payout_allocations(payout_id,entitlement_id,gross_amount,treatment,rate,wht_amount,evidence_json)
   values(p.id,(c->>'entitlement_id')::uuid,(c->>'gross')::numeric,c->>'treatment',(c->>'rate')::numeric,(c->>'wht')::numeric,c) returning id into allocation;
  if (c->>'wht')::numeric>0 then
   insert into public.finance_outgoing_wht_obligations(payout_source_id,source_line_id,source_fingerprint,payee_json,gross_base,explicit_treatment,explicit_rate,withheld_amount,withheld_on,period_month,currency,evidence_json)
    values(p.id,allocation,md5(c::text),to_jsonb(payee),(c->>'gross')::numeric,c->>'treatment',(c->>'rate')::numeric,(c->>'wht')::numeric,p.paid_on,date_trunc('month',p.paid_on)::date,'THB',c);
  end if;
 end loop;
 insert into public.finance_cash_transactions(occurred_at,direction,transaction_type,bank_account_id,cash_location_id,cash_amount,currency,status,source_payout_id,reference_no,description,created_by_user_id,updated_by_user_id,confirmed_at,confirmed_by_user_id)
  values(public.finance_bangkok_completed_day_end(p.paid_on),'outflow','other',p.bank_account_id,p.cash_location_id,p.net_amount,'THB','confirmed',p.id,upper(left(p.id::text,8)),'Payout',auth.uid(),auth.uid(),ts,auth.uid()) returning id into cash;
 perform public.record_finance_cash_transaction_audit_event(cash,'confirmed',jsonb_build_object('payout_id',p.id,'payout',snapshot,'outgoing_wht_is_not_cash_outflow',true));
 insert into public.finance_payout_audit(payout_id,event_type,version,actor_id,evidence_json) values(p.id,'confirmed',p.version+1,auth.uid(),snapshot);
 return p.id;
end;
$function$

CREATE OR REPLACE FUNCTION public.people_admin_save_profile(p_id uuid, p_input jsonb, p_expected jsonb, p_request_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare old public.user_profiles%rowtype; candidate public.user_profiles%rowtype; result jsonb;
 k text; set_clause text; identity auth.users%rowtype; allowed text[];
begin
 perform pg_advisory_xact_lock(hashtextextended('people-admin',0));
 if not public.people_is_active_admin() then raise exception 'FORBIDDEN'; end if;
 if p_id is null or jsonb_typeof(p_input) is distinct from 'object' or p_input='{}' then raise exception 'INVALID_INPUT'; end if;
 allowed:=array['full_name','staff_name','role','active','account_type','assignable','financial_access',
  'can_submit_expense_claim','can_view_own_expense_claims','can_view_all_expense_claims','can_approve_expense_claims','can_pay_expense_claims',
  'can_view_company_ledger','can_edit_company_ledger','can_void_company_ledger','can_view_lawyer_compensation','can_edit_lawyer_compensation','can_void_lawyer_compensation',
  'can_manage_finance_payments','can_confirm_finance_payments','can_reverse_finance_payments','can_reallocate_finance_payments',
  'can_view_finance_receipts','can_manage_finance_receipts','can_issue_finance_receipts','can_void_finance_receipts',
  'can_view_finance_tax_invoices','can_manage_finance_tax_invoices','can_issue_finance_tax_invoices',
  'can_view_finance_cash_transactions','can_manage_finance_cash_transactions','can_confirm_finance_cash_transactions','can_reverse_finance_cash_transactions',
  'can_view_finance_billable_charges','can_manage_finance_billable_charges','can_approve_finance_billable_charges',
  'can_submit_office_work_log','can_view_own_office_work_logs','can_view_all_office_work_logs','can_edit_office_work_logs','can_void_office_work_logs'];
 for k in select jsonb_object_keys(p_input) loop
  if k in ('full_name','staff_name','role') and jsonb_typeof(p_input->k) is distinct from 'string' then raise exception 'INVALID_INPUT'; end if;
  if not k=any(allowed) or not exists(select 1 from pg_attribute where attrelid='public.user_profiles'::regclass and attname=k and not attisdropped)
  then raise exception 'INVALID_INPUT'; end if;
  if (k in ('active','assignable','financial_access') or k like 'can\_%' escape '\') and jsonb_typeof(p_input->k) is distinct from 'boolean'
  then raise exception 'INVALID_INPUT'; end if;
 end loop;
 select * into old from public.user_profiles where id=p_id for update;
 if p_request_id is not null then
  select * into identity from auth.users where id=p_id for update;
  if identity.id is null or identity.raw_app_meta_data->>'vp_people_created_by' is distinct from auth.uid()::text
   or identity.raw_app_meta_data->>'vp_people_request' is distinct from p_request_id::text
   or identity.created_at < now()-interval '10 minutes' or identity.last_sign_in_at is not null
   or identity.banned_until is null or identity.banned_until < now()+interval '1 day'
   or p_expected is not null or (old.id is not null and old.account_type is not null)
  then raise exception 'FORBIDDEN'; end if;
  if p_input->>'account_type' not in ('operational','uat') or p_input->>'account_type' is null
   or not p_input ?& array['full_name','staff_name','role','active','account_type','assignable']
   or exists(select 1 from jsonb_object_keys(p_input) q(k) where q.k not in ('full_name','staff_name','role','active','account_type','assignable'))
  then raise exception 'INVALID_INPUT'; end if;
 else
  if old.id is null then raise exception 'NOT_FOUND'; end if;
  if p_expected is distinct from to_jsonb(old) then raise exception 'PROFILE_CHANGED'; end if;
 end if;
 candidate:=jsonb_populate_record(old,p_input);
 if candidate.role is null or candidate.role not in ('admin','partner','lawyer','assistant_lawyer','staff','viewer')
  or nullif(trim(candidate.full_name),'') is null or length(candidate.full_name)>200 or length(candidate.staff_name)>200
  or candidate.active is null or candidate.assignable is null
 then raise exception 'INVALID_INPUT'; end if;
 if candidate.assignable and (candidate.account_type is distinct from 'operational' or candidate.active is not true) then raise exception 'NOT_ASSIGNABLE'; end if;
 if old.id is null then
  insert into public.user_profiles(id,email,full_name,staff_name,role,active,account_type,assignable)
   values(p_id,identity.email,trim(candidate.full_name),trim(candidate.staff_name),candidate.role,candidate.active,candidate.account_type,candidate.assignable);
 else
  -- Only explicitly supplied keys are written; never derive Finance flags from role.
  select string_agg(format('%1$I = (jsonb_populate_record(null::public.user_profiles,$1)).%1$I',key),', ' order by key)
    into set_clause from jsonb_object_keys(p_input) q(key);
  execute format('update public.user_profiles set %s where id=$2',set_clause) using p_input,p_id;
 end if;
 select to_jsonb(u) into result from public.user_profiles u where id=p_id;
 if p_request_id is null and result is distinct from to_jsonb(old) then
  insert into public.case_audit_logs(case_id,table_name,record_id,action,user_id,user_email,user_name,user_role,old_data,new_data,note,created_at)
  select null,'user_profiles',p_id::text,'update',u.id,u.email,coalesce(u.full_name,u.email),'admin',to_jsonb(old),result,
    'Admin updated user profile',now() from public.user_profiles u where u.id=auth.uid();
 end if;
 return result;
end;
$function$
